quests[25526] = { id = 25526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Outhouse", description = "Hello? Hello! HELP!\n\nI'm almost out of air! You have to get me out of here!\n\n<The voice inside gags.>\n\nOne of those filthy Southsea treasure hunters has got to have a crowbar!", sourceObjective = "Obtain a Pirate's Crowbar and use it to pry open the Submerged Outhouse door.", progress = "Oh, for the love of profit, do you have that crowbar yet? Drowning here!", completion = "Thank goodness! Now, just a little shove....", sourceObjectiveStatus = "unverified-source-field" }
quests[25531] = { id = 25531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Riot", description = "I thank you for freeing me.  Let us take advantage of the distraction you've created and get out of here.\n\nWe must hurry before the cultists catch on.\n\nMeet me again when we've left this place.", sourceObjective = "Speak to Jarod Shadowsong at the Gates of Sothann in Hyjal.", completion = "You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25532] = { id = 25532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirate Accuracy Increasing", description = "I don't know if you've noticed, but the cannonballs are hitting us. I'd say the Southsea pirates are getting more accurate... the ship is on fire!\n\nYou've got a river boat now. Go talk to Mazzer Stripscrew.\n\nPut those fires out!", sourceObjective = "Get a River Boat from Mazzer Stripscrew and then use the Frost Cannon to extinguish 15 fires.", sourceObjectiveStatus = "unverified-source-field" }
quests[25533] = { id = 25533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirate Accuracy Increasing", description = "Oh no, {name}, the cannonballs are hitting the Speedbarge. I'd say the Southsea pirates are getting more accurate... the ship is on fire!\n\nYou've got a river boat now. Please, go speak with Griznak.\n\nExtinguish those fires!", sourceObjective = "Get a River Boat from Griznak and then use the Frost Cannon to extinguish 15 fires.", sourceObjectiveStatus = "unverified-source-field" }
quests[25534] = { id = 25534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going Off-Task", description = "As you may have seen, the ship docked to the north has its cannons blazing. While it's pretty fun watching the gnomes run face-first into a hail of iron, my bruisers keep doing it too, and it's absolutely killing my overhead expenses.\n\nI'd like you to try and dance through the cannonfire, get on that ship, and kill the taskmaster leading the cannoneers. The rest of the crew is probably a bunch of spineless prats; once he's down, we should be good.", sourceObjective = "Kill the Southsea Taskmaster.", completion = "Nice work, kid. Any close calls? Did you get grazed?\n\nNo? Good, because we've got more fish to fry here.", sourceObjectiveStatus = "unverified-source-field" }
quests[25535] = { id = 25535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Powerful Need To Eat", description = "Poor things. They're starving.\n\nWe've many matters to attend to, not the least of them the naga, but first we need to get some food in these bellies. I'm not sure what the naga fed them up in that shell, if anything, but they're definitely worse for the wear.\n\nQuite a few of the survivors have made their way into Glimmerdeep Gorge, to the northwest. Go join them and help out. With a bit of clam meat, we can get these survivors back on their feet.", sourceObjective = "Speak to Divemaster Birmingham in Glimmerdeep Gorge.", completion = "More help! Superb! We can certainly use it, I'll tell you that much.", sourceObjectiveStatus = "unverified-source-field" }
quests[25536] = { id = 25536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cold Welcome", description = "Many of the survivors made their way down into Glimmerdeep Gorge to help with the clam diving. We've been receiving reports back of deliberate attacks from some kind of murlocs down there.\n\nThe Admiral has to stay here as more men report in from the shell, so I'm having trouble convincing him to get any significant muscle to help the divers. If you'd be up for it, I'm certain they could use your help.\n\nCome back and let me know if you get the situation under control.", sourceObjective = "Kill 10 Glimmerdeep Tidehunters.", completion = "Thank you for stepping up to take care of this, {class}. I know there are a lot of concerns swarming us right now, but maintaining the safety of the survivors is paramount.", sourceObjectiveStatus = "unverified-source-field" }
quests[25537] = { id = 25537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Art of Attraction", description = "I have an idea. A brilliant idea! Those clown-looking fish have developed a symbiotic defensive relationship with the anemones. Having dismissed anemone disguise plausibilities, I've uncovered the chemical attractor that lures the fish.\n\nI have a gyrocoptic thermascrub extractor that I've brought down to take samples. Use it to extract the chemical attractor from several of the anemones, then bring the samples back to me for rapid synthesis and deployment.\n\nGo with haste! Brilliance is waiting!", sourceObjective = "Use the Anemone Chemical Extraction Device to gather 8 Anemone Chemical Samples from the red anemones along the walls of Glimmerdeep Gorge.", progress = "These chemicals are of utmost importance to my defensive diving strategies. Delay not, for we all all in murloc-laced peril!", completion = "Superb! Chemicals abound!\n\nMy instantaneous chemical synthesizer is already pre-tested and prepared. Your deployment compound shall be ready in the blink of an eye!", sourceObjectiveStatus = "unverified-source-field" }
quests[25538] = { id = 25538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Odor Coater", description = "Marvelous creation if I do say so myself. Ready for deployment.\n\nSimply spray the clam divers with a bit of the chemical and they shall soon be accompanied by a protective aquatic companion. You can even spray yourself to similar effect if you so desire.\n\nSpeaking of desire, I would highly recommend that you moderate deployment of the chemical attractor to minimal applications. Large doses could result in undesirable effects...\n\nUndesirable for you anyway. Likely very desirable for the fish.\n\nAway!", sourceObjective = "Apply the Anemone Chemical Application Device to 8 Clam Divers.", completion = "Well done my odorific associate. You are both swift and assiduous, if I do say so myself. May your future travels be rampant with inspiration and opulence.", sourceObjectiveStatus = "unverified-source-field" }
quests[25539] = { id = 25539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clamming Up", description = "Here to help with the clam diving?\n\nGet to it then. There are clams about everywhere just waiting to be dived.", sourceObjective = "Gather 16 Glimmerdeep Clams.", progress = "Has your clam-laden frolic proved fruitful?", completion = "Well done, indeed. This is an entirely unshameful amount of clams to have gathered. The survivors back at the cave will surely be grateful.", sourceObjectiveStatus = "unverified-source-field" }
quests[25540] = { id = 25540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bellies Await", description = "We have quite a stock of gathered clams to tote back to the cave, I was simply awaiting someone to do the toting. You've proven dangerous enough to be the sort.\n\nI highly expect that such a fine meal shall not pass uncontested by predators on the way back, so I'd make your trip as swift as possible.\n\nThank you for your help, friend. It's been a pleasure.", sourceObjective = "Bring the Hefty Sack Of Clams back to the Tranquil Wash.", progress = "You look to have come back to us with purpose. Was your trip successful?", completion = "This is wonderful. I will begin cooking them immediately. It is good to know that of our many fears, starvation shall no longer need to be one of them.\n\nI imagine the Admiral will have much work for you. Let me trouble you no further for a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[25541] = { id = 25541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filling Our Pockets", description = "We've looted everything that isn't bolted down around here, but I'm not done yet. If we're bothering to do the Steamwheedle Cartel's dirty work for them, we're going to make as much cash as we can while we're here.\n\nI haven't seen many earrings on these pirates, so the gold must be in the next best place...their teeth. The Southsea musketeers and strongarms to the south are the higher-ups here; they'll be the ones with the adornment. Bring me back a good fistful of gold fillings.", sourceObjective = "Collect 20 Gold Fillings from Southsea Musketeers or Southsea Strongarms.", progress = "Don't get squeamish on me now.", completion = "Nice!  Remember, gold is gold, no matter who's mouth, nose, or otherwise it's been in.\n\nIt's all perfectly sanitary after being melted down anyway. Or at least wiped off.", sourceObjectiveStatus = "unverified-source-field" }
quests[25542] = { id = 25542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Circle the Wagons... er, Boats", description = "The fires are dealt with, but there are still Southsea pirates getting ready to board the Speedbarge.\n\nTime to switch to the other side cannon and sink them before it's too late!", sourceObjective = "Sink 15 Southsea Rowboats.", completion = "You did it! You did it!\n\n<Jinky grabs you and gives you a big smooch on the cheek! She then regains her dignity and smooths her clothes.>\n\nThanks for saving my Speedbarge, Captain {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25543] = { id = 25543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Circle the Wagons... er, Boats", description = "The fires are dealt with, but there are still Southsea pirates getting ready to board the Speedbarge.\n\nTime to switch to the other side cannon and sink them before it's too late!", sourceObjective = "Sink 15 Southsea Rowboats.", progress = "I hate to say it, pal, but I think you better get back out there and sink more of those pirates before they get to the ship.\n\nSpeak with Griznak to get back on your boat!", completion = "You saved my Speedbarge!\n\n<Razzeric embraces you in a manly hug!>\n\nI can't begin to tell you how relieved I am, Captain {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25544] = { id = 25544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wave Two", description = "You've stirred up the hornets, {name}. The ceiling is coming down on us! And their strongest fighters are taking wing on creatures warped and twisted by this world of flame.\n\nGet back out there and take them down! Watch out for flaming boulders.", sourceObjective = "Equip a Twilight Firelance and fly Aviana's Guardian. Kill 10 Twilight Lancers by flying into them. Press the flap button to flap your mount's wings!", progress = "FLAP! For the love of all things merciful, flap. Flap harder!", completion = "By the wings of Aviana - you were born to fly, {name}!\n\nQuickly, let's get back out there and hit them again...", sourceObjectiveStatus = "unverified-source-field" }
quests[25545] = { id = 25545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Arms!", description = "As we struggled not to drown, my men and I were forced to abandon our weapons and much of our armor.\n\nErunak says to expect a major attack from the naga soon and I'm inclined to believe him.\n\nIf we're going to stand a chance, we'll need your help to recover our lost armaments. They should be lying on the sea floor near our shipwrecks.\n\nHurry, {race}, we're defenseless here.", sourceObjective = "Gather 4 Stormwind Spears, 4 Stormwind Breastplates, 4 Stormwind Shields and 4 Stormwind Helms.\n\nThe equipment may also be collected from Gliblin Scavengers.", progress = "Have you recovered our gear, {race}?", completion = "Well done, {class}!\n\nThanks to you, my men will be ready to confront the enemy when they attack.", sourceObjectiveStatus = "unverified-source-field" }
quests[25546] = { id = 25546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traveling on Our Stomachs", description = "I'll need your help if I am to get these men ready for battle.\n\nAny decent leader knows that his men travel and fight on their stomachs. No food, no victory.\n\nThese soldiers are weak from their recent ordeal. They'll need sustenance if they're to put up any kind of fight when the need arises.\n\nSpeaking of traveling on stomachs, I've seen several crabs out there on the sea floor....", sourceObjective = "Collect 8 Succulent Crab Meat from Splitclaw Skitterers.", progress = "Were you able to find anything for my men and I to eat, {class}?", completion = "This should help relieve our exhaustion.\n\nAgain, we thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25547] = { id = 25547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Our Own Terms", description = "We're as ready as we'll ever be. No sense waiting around for the naga to find us.\n\nI'll address the men, then we'll meet the enemy on our own terms and let fate decide the outcome.", sourceObjective = "Speak to Captain Taylor in the Briny Cutter.", completion = "No time to address the troops now.\n\nJust as well. They know what must be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[25548] = { id = 25548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Might of the Firelord", description = "I've been charged with leading our military operations against the enemy.  A humbling task when you consider there are demigods walking among us.\n\nI'm going to have you carry out a series of hit-and-run attacks behind enemy lines.  It will be important that you keep the enemy off guard and weaken their numbers ahead of our main force's attack.\n\nYour first target will be the Ascendant's Rise, where the most highly trained Twilight's Hammer devotees have achieved a partial elemental state.", sourceObjective = "Slay 4 Flame Ascendants and 5 Twilight Subjugators at the Ascendant's Rise in Hyjal.", completion = "You did well, {name}.  I've a new target for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25549] = { id = 25549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sanctum of the Prophets", description = "The mad prophets of the Twilight's Hammer congregate in the area just north of the Ascendant's Rise.\n\nIt is said that their dark visions are granted to them directly by the Old Gods.  Whether or not that is true, they provide tremendous spiritual guidance to the cult.  Attacking the Sanctum of the Prophets will deal a devastating blow to the enemy's morale and if we're lucky you might run into one of the Firelord's own emissaries while you're there.", sourceObjective = "Slay 4 Twilight Augurs, 4 Twilight Retainers and 1 Emissary of Flame at the Sanctum of the Prophets.", completion = "You continue to prove your prowess, {name}.  At this rate Hyjal might survive this ordeal after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[25550] = { id = 25550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magma Monarch", description = "The magma giants who serve Ragnaros are kept in line by their king's heavy-handed rule.  Were we to take care of him, the rest will surely fall into disarray.\n\nWithout the giants, the fight on the ground will get a lot more even.  Perhaps even tilt to our favor.\n\nBut felling the magma monarch will be no easy task.  Use these drums to enlist the help of the great Tortolla who is capable of holding off King Moltron for an eternity.  But holding him off won't be enough -- and that's where you come in.", sourceObjective = "Use the Drums of the Turtle God to help you defeat King Moltron.", progress = "Yes, {name}?", completion = "Excellent work, {name}.  We shall soon claim victory in Hyjal.\n\nIt has been an honor to fight along your side.", sourceObjectiveStatus = "unverified-source-field" }
quests[25551] = { id = 25551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Firelord", description = "With his gatekeeper gone, you've given the Guardians of Hyjal access to Sulfuron Spire.\n\nRagnaros will have no choice but to defend the main entryway to the Firelands himself.\n\nGo through the Twilight's Hammer portal at the Sanctum of the Prophets and meet me inside.  Malfurion and Hamuul will also aid us while the others continue to fight the enemy outside.", sourceObjective = "Go through the portal at the Sanctum of the Prophets and aid Cenarius in defeating Ragnaros.", progress = "Yes, {name}?", completion = "Hyjal has been saved, {name}.  And it's all thanks to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25552] = { id = 25552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brood of Evil", description = "This egg you recovered is an alarming sign, {name}.  The Twilight dragons are usually raised from stolen eggs from other dragonflights, which are then modified through dark magic.\n\nThis \"natural\" egg is evidence that one of their matriarchs has become a viable broodmother.  We must destroy her before her brood spreads.\n\nGo to the Ascendant's Rise where they claim these aberrations are kept and slay one of the juvenile drakes.  We will use its skull to lure out its mother.", sourceObjective = "Obtain a Young Twilight Drake's Skull at the Ascendant's Rise in Hyjal.", progress = "You've returned, {race}.", completion = "You've done well, {name}.  We will use this to draw out the Twilight matriarch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25553] = { id = 25553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Broodmother", description = "We've located the matriarch's feeding grounds south of the Ascendant's Rise.\n\nShe will be extremely angry to have lost one of her drakes.  Place the skull there near the carcasses she devours.  If she's anywhere in the vicinity, she will come out and attempt to exact revenge.\n\nWe will have a surprise waiting for her.", sourceObjective = "Place the Twilight Drake Skull at the feeding grounds south of the Ascendant's Rise and slay Desperiona.", progress = "It's good to see you, {name}.", completion = "That went... better than expected.", sourceObjectiveStatus = "unverified-source-field" }
quests[25554] = { id = 25554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Flame", description = "If we are to banish Ragnaros back into the Firelands, we will need to gain access to Sulfuron Spire.\n\nOnly the most trusted members of the Twilight's Hammer will have been entrusted with such valuable information.\n\nGo search the Ascendant's Rise for any written tomes you might find.  Foul as they are, we cannot waste the opportunity to learn about our enemy's weaknesses.", sourceObjective = "Obtain the Ascendant's Codex, the Burning Litanies and the Tome of Flame at the Ascendant's Rise in Hyjal.", progress = "Did you succeed in your task, {name}?", completion = "These foul books should not be allowed to exist.  Yet the information inside them is of vital importance.", sourceObjectiveStatus = "unverified-source-field" }
quests[25555] = { id = 25555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gatekeeper", description = "According to these tomes, one of Ragnaros' most powerful lieutenants serves as the sole gatekeeper to Sulfuron Spire.\n\nYou won't be able to defeat him alone.\n\nSound this horn when you engage in combat with Azralon and any of our forces in the vicinity will come to your aid.\n\nYou must hurry, {name}.  It won't be long before the Firelord realizes what we're up to.", sourceObjective = "Use the Horn of Cenarius to help you slay Azralon the Gatekeeper.", progress = "You've returned, {name}?", completion = "It is done.  Only the final step in your mission remains.", sourceObjectiveStatus = "unverified-source-field" }
quests[25556] = { id = 25556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Zul'Farrak", description = "That foul traitor...I should've known better than to trust his kind. My hunt for Sul'thraze has blinded me.\n\nForgive me, {name}. Mazoga has fled inside of Zul'Farrak, the heart of the Sandfury civilization.\n\nIf you truly seek the sword, you must pursue him. Do not go alone; the entirety of the Sandfury tribe lies in wait behind those walls, and they will not welcome you.\n\nI will stay here. My search for the blade must end. Should you find it, keep it; I must give up before I am consumed.", sourceObjective = "Find Mazoga within Zul'Farrak.", completion = "<Mazoga's ghost gives you a blood-smeared grin.>\n\nHow you doin', mon?", sourceObjectiveStatus = "unverified-source-field" }
quests[25558] = { id = 25558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All or Nothing", description = "This is it.\n\nThis is where we make our stand.\n\nWe must defend this ship to our last breath, and make these cretins think twice before approaching it again!\n\nMay our blades strike fear in their hearts!", sourceObjective = "Assist Captain Taylor in the defense of The Briny Cutter.", completion = "The Earthen Ring has received my distress message and sent help - just in time it would seem.\n\nHopefully more can be sent soon. We are but few against a great many.", sourceObjectiveStatus = "unverified-source-field" }
quests[25559] = { id = 25559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laying Claim", description = "We're not the only ones interested in these ruins, it seem. Of all things, we've got blood elves after our dig sites.\n\nI'd expect them to wilt in the heat without all their fancy fountains and cushy pillows, but they're surprisingly scrappy, and they're trying to drive us out of the Southmoon Ruins by force.\n\nIt's time to crack a few heads. Head over there and teach those elves not to mess with us!", sourceObjective = "Kill 10 Blood Elf Ruins Hunters.", completion = "That'll teach the Horde twofold! Don't mess with dwarven history, and don't send a bunch of frail couch-dwellers to do your fighting!", sourceObjectiveStatus = "unverified-source-field" }
quests[25560] = { id = 25560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg Wave", description = "Without any defenders, the Firelands eggs are vulnerable.\n\nTake wing once more and smash those eggs! Simply rush over them to crush them. Search all the nooks, crannies, and side-caves. Hurry!", sourceObjective = "Equip a Twilight Firelance and fly Aviana's Guardian. Smash 40 Firelands Eggs by running over them. Press the flap button to flap your mount's wings!", progress = "Have you cracked a few eggs?\n\nI don't even want to know what the Twilight's Hammer was breeding down here...", completion = "A decisive blow!", sourceObjectiveStatus = "unverified-source-field" }
quests[25561] = { id = 25561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Circle the Wagons... er, Boats", description = "The fires may be dealt with, but those Southsea pirates are still getting ready to board the Speedbarge!\n\n{name}, you need to go back to Mazzer Stripscrew and get on your boat. Use the cannon to sink them before it's too late!", sourceObjective = "Sink 15 Southsea Rowboats.", sourceObjectiveStatus = "unverified-source-field" }
quests[25562] = { id = 25562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Circle the Wagons... er, Boats", description = "The fires may be dealt with, but those Southsea pirates are still getting ready to board the Speedbarge!\n\n{name}, you need to go back to Griznak and get on your boat. Use the cannon to sink them before it's too late!", sourceObjective = "Sink 15 Southsea Rowboats.", sourceObjectiveStatus = "unverified-source-field" }
quests[25564] = { id = 25564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormwind Elite Aquatic and Land Forces", description = "You've done us a great service, {class}, so I'm going to let you in on a little secret. The men you've saved today aren't your everyday Stormwind troops.\n\nWe belong to a special detachment of elite soldiers sent here not only to contend with the Horde, but to investigate the massive geological disturbances originating from the nearby sea floor.\n\nI tell you this because our top secret equipment lies in the bottom of some of our wrecked ships here.\n\nThat gear must be retrieved!", sourceObjective = "Find 6 Stormwind SEAL Equipment.", progress = "Were you able to secure that equipment, {class}?", completion = "Everything here seems to be in working order.", sourceObjectiveStatus = "unverified-source-field" }
quests[25565] = { id = 25565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragments of Language", description = "We've had our first big find in years here at the Southmoon ruins. My lads have dug up stone tablets, engraved with ancient writings.\n\nThe glyphs on the tablets are like nothing we've ever seen, but I have a hunch we can connect them with titanic scripts found at other digsites. Imagine what a breakthrough like that could mean!\n\n I need you to go to the Southmoon ruins and help us collect the tablets; the other lads can't leave, lest the blood elves take our site!", sourceObjective = "Collect 5 Ancient Hieroglyphs.", progress = "Do you have the tablets?", completion = "Would you take a look at these...not troll, not qiraji, just pure mystery waiting to be unlocked.\n\nThese aren't going anywhere now that they're safely in our hands. It's time to make our way into the ruins!", sourceObjectiveStatus = "unverified-source-field" }
quests[25566] = { id = 25566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secrets of Uldum", description = "I studied these ruins for years trying to find a way in. We even took a good chunk out of the gate, only to find impenetrable walls beneath. Now the cataclysm may've wrecked everything in there something fierce, but it's done what we couldn't and opened a way in!\n\nI'd like you to have the honor, <lad/lass>. Head on in there and see if anything's been left uncracked. Be careful though... there's no telling what, or who, might be stirring in there.", sourceObjective = "Search the Antechamber of Uldum for an intact artifact.", completion = "This chest lies undisturbed, sealed for thousands of years.", sourceObjectiveStatus = "unverified-source-field" }
quests[25571] = { id = 25571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Natural Occurrence", description = "This Elemental Shard is all that is left from the rift that stood here before.  The connection between the shard and the rift is unknown, but perhaps someone more versed in the elements would know more.\n\nSeek out an Earthen Ring Emissary in any capital city.  This could be exactly what they are looking for.", sourceObjective = "Take the Elemental Shard to an Earthen Ring Emissary in Orgrimmar, Undercity, Thunder Bluff or Silvermoon.", sourceObjectiveStatus = "unverified-source-field" }
quests[25574] = { id = 25574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flames from Above", description = "We've identified the general direction where the infiltrators have been coming from, thanks to your work.\n\nNow we just need to shut down their camp and put an end to their operations this side of Nordrassil.\n\nTake this horn.  It will signal one of our emerald drakes to swoop down and give these Twilight cultists a taste of the flames they so madly worship.", sourceObjective = "Seek the Twilight Encampment north of Nordrassil and use Tholo's Horn.", progress = "Is it done yet, {name}?", completion = "Excellent, {name}.  That should put a stop to the attacks once we finish these elementals off.", sourceObjectiveStatus = "unverified-source-field" }
quests[25575] = { id = 25575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forged of Shadow and Flame", description = "The weapons the Twilight's Hammer uses against us are crafted by Forgemaster Pyrenduis within these very halls. The metal slices through armor like cheese in the hands of its wielder. Yet, when captured, the steel turns brittle and shatters.\n\nSo be it, {name}. I'd rather see those cursed arms smashed than delivered to our enemy.\n\nSeek out the crates of Twilight arms in these caverns and smash them to pieces.", sourceObjective = "Destroy 10 Twilight Arms crates.", completion = "Good, good. I like nothing more than to see the works of our enemy destroyed.", sourceObjectiveStatus = "unverified-source-field" }
quests[25576] = { id = 25576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rage of the Wolf Ancient", description = "Here we are deep within the realm of the fire god and what do we find? The little puppets of Ragnaros, scurrying around to do his bidding.\n\nThese Dark Iron laborers are finishing and packaging the weapons Twilight's Hammer hopes to use in their conquest of Hyjal. I don't care if they're here of their own free will or if they've been brainwashed or kidnapped... They're a foe of our beloved wolf ancient and they should pay the ultimate price.", sourceObjective = "Slay 12 Dark Iron Laborers.", progress = "It's okay to revel in the destruction of deserving foes, {class}. How goes the fight?", completion = "Dead? Good. They sealed their fate when they threw their lot in with Ragnaros and his kingdom of flame.\n\nLeave their bodies down here to crumble into ash.", sourceObjectiveStatus = "unverified-source-field" }
quests[25577] = { id = 25577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Cores", description = "These searing guardians are murderous! We destroy them, and within minutes, they reignite from the ashes.\n\nI think there's a way to destroy them permanently, but we'll need someone who can fight through the front ranks.\n\n{name}, kill the searing guardians and take their smoldering cores to the nearby anvils. Smash them on the Twilight Anvils, and destroy them for good!", sourceObjective = "Acquire 8 Smoldering Cores by killing Searing Guardians, then smash them against a Twilight Anvil.", progress = "Are they dead?\n\nIt seems like nothing we do can cool this inferno...", completion = "Great work!\n\nThere was a time when adventurers would collect these cores in order to craft mediocre fire-resistant equipment. But for now, I'm glad just to destroy these fiends once and for all.", sourceObjectiveStatus = "unverified-source-field" }
quests[25578] = { id = 25578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Nordrassil", description = "I will take Fandral to Moonglade swiftly.  I hope to return soon so I may continue to aid in the battle.\n\nIn the meantime, report back to Ysera and inform her of these recent developments.", sourceObjective = "Speak to Ysera at Nordrassil in Hyjal.", completion = "Alysra's decision might not have been the wisest, {name}.  Yet there is little time to worry about that now.\n\nI bring important discoveries from the Emerald Dream.", sourceObjectiveStatus = "unverified-source-field" }
quests[25579] = { id = 25579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caught Off-Guard", description = "Our escape from the shell can't have gone unnoticed, but either the naga at these ruins weren't informed or they don't consider us a threat. I don't intend to take the opportunity for granted - we strike now.\n\nI need you to slip into the lower level of the ruins to our west and take out as many of their patrols as you can. We cannot risk any of those patrols finding out about our occupation of this cave - make sure none escape.", sourceObjective = "Kill 10 Azsh'ir Patrollers.", completion = "Excellent work, {class}.\n\nI will get some of our own patrols out to make sure that no more naga get within sight of this cave. We should have the area secured within the hour.", sourceObjectiveStatus = "unverified-source-field" }
quests[25580] = { id = 25580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swift Approach", description = "I've taken the liberty of performing some preliminary scouting. The naga may not be aware of our position, but they are not entirely unprepared for intruders.\n\nBeyond their patrols, they have set up magical sentry devices that will warn them of unwelcome guests. Fortunately, they seem to have sacrificed quality for quantity, and there is definitely a window in which the devices can be destroyed before their alarms are answered.\n\nI trust that you can see to this before our other soldiers arrive.", sourceObjective = "Destroy 8 Azsh'ir Monitors.", completion = "Well done, {name}, and just in time too. The Admiral just started sending more men out. Strong sword arms to be sure, but I doubt they possess quite the same awareness and finesse that you do.\n\nWe were lucky to have you here when things went south. I suspect you will have a large role to play in things to come as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[25581] = { id = 25581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Occupation of Time", description = "Look--{name} is it?--I need your help. I know most everyone in this cave thinks that we're not in a position to be worrying about anything but our own hides right now, but I cannot dismiss my ancestors so readily.\n\nAll I want from you, while you're out in the city proper, is to keep a watchful eye out for objects of significance. The statues interest me especially.", sourceObjective = "Investigate the 4 intact statues in the Vashj'ir Gardens.", completion = "Thank you so much for taking this seriously.\n\nThis is some of the first definitive proof of other members of the Vashj family. Very interesting. And I'd never even heard of either of the other two figures you mentioned until now.\n\nSo much of our history was lost during the sundering - it's exciting to have a chance at reclaiming some of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[25582] = { id = 25582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Better Vantage", description = "This cave is our only refuge. There's no help on the way. Whatever happens, this cave must remain safe or we are all sure to die down here.\n\nWe need a forward post to launch our attacks from. Something defensible.\n\nIn the eastern portion of the ruins on the lowest level, scout the north end of the gardens, the passage leading under the main structure just west of the gardens, and the cluster of buildings at the southeast corner of the ruins, under the bridges.\n\nBring me back any information you can.", sourceObjective = "On the lowest level of the ruins, scout the northern end of the Quel'Dormir Gardens, the passage that leads under the ruins west of the gardens, and the structures at the southeast corner of the ruins, below the bridges.", completion = "This is good intel. You have a sharp eye, {class}.\n\nIt sounds like the building tucked under the terrace at the far end of the ruins will make a suitable forward post. I will send some men immediately to start defensive preparations and we will reposition there as soon as possible.", sourceObjectiveStatus = "unverified-source-field" }
quests[25583] = { id = 25583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upon the Scene of Battle", description = "All around you lie the remnants of a fierce battle. The naga skeletons are no surprise, but the weapons and remains of their apparent opponents are somewhat more unexpected.\n\nAmidst the bones, you spot a strangely prominent piece of metal jutting out from one of the skulls. It's difficult to tell what sort of weapon it might have once been part of, but it stands out sufficiently to prompt you to retrieve it as evidence.\n\nSurely someone back at the cave would be interested in this revelation.", sourceObjective = "Bring the broken shard back to the Tranquil Wash.", progress = "Yes, {class}?", completion = "Interesting indeed.\n\nThe remains you describe sound much like the sea vrykul we encountered in Northrend. I highly doubt we will be striking any alliances with their sort, no matter the cause. Still, this information may prove useful in the future.\n\nI will think on it further if time permits. Thank you for bringing it to my attention.", sourceObjectiveStatus = "unverified-source-field" }
quests[25584] = { id = 25584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Return of the Ancients", description = "It'll be crucial to reclaim each of the ancients' shrines, {name}.\n\nFollow the road west of the Verdant Thicket, into Wolf's Run.\n\nWe have operatives stationed there.  Aid them in any way that you can and work your way to the first shrine.\n\nThe wolf god was known to the elves as Goldrinn and to the orcs as Lo'Gosh.  He will be a fierce ally in our fight against the enemy.", sourceObjective = "Speak to Oomla Whitehorn at Wolf's Run in Hyjal.", completion = "Ysera sent you? Good! We need all the help we can get.\n\nWe'll never be able to recover the shrines to the ancients so long as Twilight's Hammer controls the roads. Somehow we've got to stem the flood.", sourceObjectiveStatus = "unverified-source-field" }
quests[25585] = { id = 25585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quiet the Cannons", description = "Now it's time to do something about those darn cannons up on the bluffs to the east!\n\nIf you'd be so kind, hop into your boat and cruise on over to the Southsea Holdfast. Up top you'll see a bunch of cannons firing down on us.\n\nThose pirates don't know squat about engineering. It shouldn't be too difficult for you to clog 'em up and make them explode.", sourceObjective = "Destroy 8 Holdfast Cannons.", completion = "They're still shooting, but not nearly as much! Yeeeeeeeeeaaaaaaaaaaah!", sourceObjectiveStatus = "unverified-source-field" }
quests[25586] = { id = 25586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quiet the Cannons", description = "Now it's time to do something about those darn cannons up on the bluffs to the east!\n\nIf you'd be so kind, hop into your boat and cruise on over to the Southsea Holdfast. Up top you'll see a bunch of cannons firing down on us.\n\nThose pirates don't know squat about engineering. It shouldn't be too difficult for you to clog 'em up and make them explode.", sourceObjective = "Destroy 8 Holdfast Cannons.", completion = "They're still shooting, but not nearly as much! Yeeeeeeeeeaaaaaaaaaaah!", sourceObjectiveStatus = "unverified-source-field" }
quests[25587] = { id = 25587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gimme Shelter!", description = "Please, {race}! You must help me!\n\nI've barely managed to survive, what with naga, sharks, and that horrible monster that attacked our ship.\n\nI can see a cave that might be safe, but I don't dare try to make it unless I know there's air inside.\n\nCan you make sure it's ok?", sourceObjective = "Investigate Smuggler's Scar in the Kelp'thar forest, then signal to Adarrah that it's safe to enter.", completion = "I cannot thank you enough, {race}.\n\nI just hope this whole nightmare has a happy ending.", sourceObjectiveStatus = "unverified-source-field" }
quests[25588] = { id = 25588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Payback", description = "It's time for a little payback, I think. Can you blame me? After they locked me down in that outhouse and left me to drown?!\n\nI'll make it worth your while if you head up to the Southsea Holdfast on the eastern bluffs and exact my revenge.", sourceObjective = "Slay 15 Southsea pirates at the Southsea Holdfast.", completion = "That'll teach those scurvy dogs! You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25589] = { id = 25589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Payback", description = "It's time for a little payback, I think. Can you blame me? After they locked me down in that outhouse and left me to drown?!\n\nI'll make it worth your while if you head up to the Southsea Holdfast on the eastern bluffs and exact my revenge.", sourceObjective = "Slay 15 Southsea pirates at the Southsea Holdfast.", completion = "That'll teach those scurvy dogs! You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25590] = { id = 25590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's Wizzle?", description = "Hey, {name}, you haven't seen my other brother, Wizzle, have you?\n\nI just know that the pirates captured him! He said that he was going to try to sell them some engineering stuff, or something.\n\nWould you please look for him up at the Southsea Holdfast to the east? I'll bet that no-good goblin he's always traveling with, Synge, got him into trouble!", sourceObjective = "Find Wizzle Brassbolts at the Southsea Holdfast in Thousand Needles.", completion = "Hey! Get me out of here!", sourceObjectiveStatus = "unverified-source-field" }
quests[25591] = { id = 25591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderdrome: Grudge Match!", description = "It seems we have a special request! I have here a note from one Megs Dreadshredder, requesting to enter the cage and settle a dispute.\n\nShe's asked for you to be her partner, {name}. A fan of your previous victories? Or perhaps you're acquainted outside the ring?\n\nI wouldn't back down now if I were you. This is the grand finale...", sourceObjective = "Defeat Kelsey Steelspark.", progress = "Stop wasting my time. Enter and fight!", completion = "Fantastic. I might challenge you to a duel myself someday.", sourceObjectiveStatus = "unverified-source-field" }
quests[25592] = { id = 25592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Attraction", description = "I've been able to help some of the survivors make it to the cave, but it's starting to get hairy out there. If we didn't have enough problems, some glowing murlocs started creeping up from the nearby crevice to attack the stranded survivors.\n\nThe men up there are warriors--they won't go down without a fight--but they're much worse for the wear after that damned shell.\n\nIf you have any breath left in your lungs, get up there and take out some of those murlocs. Hellscream's eyes are upon you.", sourceObjective = "Kill 10 Redgill Scavengers.", completion = "You know what it is to carry yourself with honor, {class}. You do Hellscream proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[25593] = { id = 25593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shelled Salvation", description = "A lot of the men haven't made it to the cave yet. It's a safe bet that they're stranded at the vents on the ridge above us.\n\nWe found some spiralung shells on the way here. They don't produce much air, but it was enough for us to make the cave.\n\nI need to stay here to count heads and get them back on their feet as they arrive. Do me a favor - go collect those spiralung shells, get them to any of my men that are still up on the ridge, and give them a swift kick in the arse so that they get moving.", sourceObjective = "Collect 8 Spiralung shells and give them to stranded Nespirah Survivors.", completion = "Thank you, {class}. You've proven very useful.", sourceObjectiveStatus = "unverified-source-field" }
quests[25594] = { id = 25594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafty Crabs", description = "It was that darn crab!\n\nHere I thought that all the exercise from walking here was making me super buff! My pack just kept getting lighter and lighter. But no! That crab snipped a hole in my bag and all my parts were falling out the whole way here.\n\nPlease, help a good lookin' goblin out, will ya? Go back and help me pick up all of my stray parts. I'm sure those conniving vicious little crabs ran off with some of them too.", sourceObjective = "Collect 12 of Fiasco's Stray Parts.", progress = "Never underestimate the appeal of something shiny.", completion = "Glad you know a quick buck when you see one. Pleasure doing business with you, buddy.", sourceObjectiveStatus = "unverified-source-field" }
quests[25595] = { id = 25595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Edible", description = "Were they trying to starve us all to death?! Not giving prisoners food is just despicable.\n\nWe need to get these soldiers fed. The best prospect I spotted on the way here were those giant grouper. Several of those and we shouldn't want for meat for a while.\n\nIf you can bring me back some, I'll see to it that it gets cooked and passed out fairly.", sourceObjective = "Collect 8 Snapjaw Grouper Meat.", progress = "With all the rumbling bellies, it sounds like there's a monster in this cave. It's putting my nerves on edge.", completion = "Now to hold up my end of the bargain. I'll get this cooked and passed out immediately.\n\nYou and I will have to have a talk later. I'm going to need help that these soldiers just can't offer.", sourceObjectiveStatus = "unverified-source-field" }
quests[25596] = { id = 25596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's Synge?", description = "Hey, {name}, you haven't seen our gunsmith, Synge, have you?\n\nI just know that the pirates captured him! He said that he was going to try to sell them some rifles, or something.\n\nWould you please look for him up at the Southsea Holdfast to the east? I'll bet that no-good gnome he's always traveling with, Wizzle Brassbolts, got him into trouble!", sourceObjective = "Find Synge at the Southsea Holdfast in Thousand Needles.", completion = "Hey! Get me out of here!", sourceObjectiveStatus = "unverified-source-field" }
quests[25597] = { id = 25597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander Jarod Shadowsong", description = "Only once has there been a leader capable of commanding demigods and mortals alike.\n\nHis name was Jarod Shadowsong and his ability to lead in battle was such that Cenarius and the other ancients placed themselves under his command.\n\nHe disappeared for years and his whereabouts were unknown.  Until now.\n\nHe is being held captive inside a Twilight camp in Darkwhisper Gorge.\n\nYour job is to infiltrate their ranks and free Jarod.  Speak to the one known as Ortell at Darkwhisper Pass to the southeast.", sourceObjective = "Speak to Elementalist Ortell at Darkwhisper Pass.", completion = "Hey there.  I'm glad to see they sent someone of your caliber for this operation.\n\nThis here's going to call for some subtlety.  We can't risk Commander Shadowsong getting killed.", sourceObjectiveStatus = "unverified-source-field" }
quests[25598] = { id = 25598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ain't Too Proud to Beg", description = "Now that you've brought me to safety, I'm afraid I must impose upon your kindness just a bit further.\n\nThe captain of our ship, Samir, is still out there. Mack too. I'm sure they made it to the sea floor but beyond that I didn't see what became of them.\n\nI simply couldn't get by in a place like this without their help.\n\nI lost sight of them in a clump of kelp west of where you found me.\n\nPlease hurry! They couldn't have gotten far...", sourceObjective = "Find Samir and Mack.", progress = "Well, {name}? Did you find them?", completion = "Where would we be without you, {race}!\n\nI don't want to even imagine!", sourceObjectiveStatus = "unverified-source-field" }
quests[25599] = { id = 25599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cindermaul, the Portal Master", description = "Twilight's Hammer is using these corridors, and others like them, to move supplies from the elemental planes up into Azeroth. In order to seal these passages off, we're going to need to know how they're constructed.\n\nFind for me the Tome of Openings, used by the elementals to open gates between the planes.\n\nCindermaul the Portal Master should have one. You'll have to kill him. Careful! He's probably got some tricks up his sleeve...", sourceObjective = "Slay Cindermaul and locate the Tome of Openings.", progress = "The tome! Have you found it?", completion = "This is the tome we've heard about?\n\n<Jordan hefts the stone slab into his arms and looks it over.>\n\nI see... I guess it's good that I can read some of the elemental script. I'll work on translating this. Meanwhile, there's one final problem to take care of.", sourceObjectiveStatus = "unverified-source-field" }
quests[25600] = { id = 25600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgemaster Pyrendius", description = "A terrible evil squats in the heart of this cavern, {name}. Forgemaster Pyrendius has personally crafted many of the cursed weapons that Twilight's Hammer is using in their conquest of the realms above.\n\nBefore we leave these lands of flame... Pyrendius must die.\n\nHe will not go down easy. But, if I'm reading the tome correctly, we can briefly open up small gateways to the Abyssal Maw, the realm of water. Lure Pyrendius onto a portal rune and activate it to weaken him!", sourceObjective = "Slay Forgemaster Pyrendius. Lure him onto the Portal Runes and use them to weaken him.", progress = "Is Pyrendius dead? This ashen heat of this cave is suffocating me!", completion = "It is done! We'll seal this fiery hole up behind us and let the minions of the Twilight's Hammer discover the corpses we left behind. We couldn't have done it without you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25601] = { id = 25601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head of the Class", description = "That settles it, \"{name}damus!\"  You are head of your class!\n\nYou will get a chance to address a crowd of the most fanatical, bloodthirsty and certifiably insane people on this planet.\n\nGo report to your instructor for the details, but remember: your goal is to exploit the animosity between the ogres at the Seat of the Chosen and the other, less privileged races.\n\nIf all goes well, we will smuggle Jarod out of here during the ensuing riot.", sourceObjective = "Speak to instructor Mylva at the Forge of Supplication in Hyjal.", completion = "There you are, Beefshammichdamus.  I've been meaning to talk to you about something.\n\nI heard about the unfortunate incident that befell our poor friend, Okrog.\n\n<Mylva looks to her left, then her right.  She finally nods and shoots a sly wink in your direction.>\n\nYou might be a better pupil than I had thought.", sourceObjectiveStatus = "unverified-source-field" }
quests[25602] = { id = 25602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Start a Fire Without a Spark", description = "Mack's still out of it, and I fear we may lose him if I can't get this fire started. With the wood being soaked, we'll need something special to get it going.\n\nThere's an abandoned camp nearby with a barrel of explosives in it. There's no way I can recover it on my own.\n\nWould you mind hauling it back for us? For Mack?", sourceObjective = "Get the Keg of Gunpowder from Budd's Dig.", progress = "Did you get the explosives from the camp, {class}?", completion = "Outstanding!\n\nLet's see if this does the trick....\n\nStand back, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25607] = { id = 25607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ze Gnomecorder", description = "Zese goblinz dizgust me. Zer filzy goblin technology iz inferior to anyzing gnomish, yet...\n\n<Professor Xakxak sighs.>\n\nIt iz ze last piece of ze puzzle! Wizout ze filzy goblin technology ze gnomecorder cannot be built!\n\nVenture eazt into ze \"Skunkworks\" and take from zem zer filzy goblin junk! You vill most likely find zem on goblin technicians.\n\n<Professor Xakxak laughs mockingly.>\n\nGoblin technician? Vut iz zat anyvay?\n\n<Professor Xakxak shrugs.>\n\nZome kind of oxymoron?", sourceObjective = "Recover 8 pieces of Filthy Goblin Technology.", progress = "Ze junk? Do you have zit?", completion = "Ah, ze junk haz arrived! Zit is ze last piece of ze puzzle! Now to zet it up! Standby, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25608] = { id = 25608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slash and Burn", description = "Victory is possible, {name}.\n\nThis portal is not just a means of bringing back Cenarius through the dream.  Think about it, {name}.  Once a gateway through the Emerald Dream is open, our forces can use them to move freely from Moonglade, Nordrassil, and even Wyrmrest, to this strategic location.\n\nAll Ysera needs is time. It'll be up to you to keep the Twilight's Hammer forces in Darkwhisper Gorge from pulling together and attacking us from the east.\n\nTake one of the emerald drakes and hit them hard, {name}.", sourceObjective = "Ride an Emerald Drake and slay 40 Twilight's Hammer units and 5 Twilight Drakes.", progress = "You've returned, {name}.", completion = "Excellent work, {name}.  We might win this one yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25609] = { id = 25609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunken Treasure", description = "The key to the cage is held by Tony Two-Tusk, the pirate admiral, and he's guarded by ogres that you'll never be able to kill!\n\n<Wizzle cries some more and then looks up, an idea forming in his brain.>\n\nI've got it! What do all pirates want more than anything else? No, not grog. Something even better... treasure!\n\nThey had a ship full of treasure that was sunk by a giant whale-shark. The treasure is scattered all over down in the Mirage Abyss to the northwest.\n\nGo get it!", sourceObjective = "Collect 8 Sunken Treasure Chests.", progress = "Oh gosh, do you already have all of that sunken treasure?", completion = "Oh yeah! Look at all that booty.\n\nWait a minute... bring it closer!", sourceObjectiveStatus = "unverified-source-field" }
quests[25610] = { id = 25610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunken Treasure", description = "The key to the cage is held by Tony Two-Tusk, the pirate admiral, and he's guarded by ogres that you'll never be able to kill!\n\n<Wizzle cries some more and then looks up, an idea forming in his brain.>\n\nI've got it! What do all pirates want more than anything else? No, not grog. Something even better... treasure!\n\nThey had a ship full of treasure that was sunk by a giant whale-shark. The treasure is scattered all over down in the Mirage Abyss to the northwest.\n\nGo get it!", sourceObjective = "Collect 8 Sunken Treasure Chests.", progress = "You already have all of that sunken treasure?", completion = "Oh yeah! Look at all that booty.\n\nWait a minute... bring it closer!", sourceObjectiveStatus = "unverified-source-field" }
quests[25611] = { id = 25611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return from the Firelands", description = "I'll usher out the rest of Goldrinn's followers and seal this portal behind us.\n\nThe rest of our forces at Mount Hyjal will want to hear of this victory. Return to Ian Duran and let him know what we've discovered and how we were triumphant!\n\nSimply step through the portal to return to Mount Hyjal.", sourceObjective = "Return to Ian Duran at the Shrine of Goldrinn in Hyjal.", completion = "They're moving supplies to Hyjal straight from the elemental planes? That explains so much.\n\nYou've made Goldrinn proud by sealing that flamegate, {name}, but there may be more portals to seal. You should check with the other shrines!", sourceObjectiveStatus = "unverified-source-field" }
quests[25612] = { id = 25612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return from the Firelands", description = "I'll usher out the rest of the followers of Lo'Gosh and seal this portal behind us.\n\nThe rest of our forces at Mount Hyjal will want to hear of this victory. Return to Takrik Ragehowl and let him know what we've discovered and how we were triumphant!\n\nSimply step through the portal to return to Mount Hyjal.", sourceObjective = "Return to Takrik Ragehowl at the Shrine of Goldrinn in Hyjal.", completion = "They're moving supplies to Hyjal straight from the elemental planes? Devious.\n\nYou've made Lo'Gosh proud by sealing that flamegate, {name}, but there may be more portals to seal. You should check with the other shrines!", sourceObjectiveStatus = "unverified-source-field" }
quests[25613] = { id = 25613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Yourself a Favor", description = "So these night elves send out a desperate call for help to us, goes something like this:\n\n<Gnombus changes the pitch of his voice to sound like a woman.>\n\n\"Please come help us! The big, mean Horde has goblins! Oh, we can't handle goblins! They pull our hair and make us cry!\"\n\nRight, anyway, so here we are.\n\nThe first thing I did was upgrade their aerial defenses with some of my new sniper guns. Problem is, they don't use guns. Do yourself a favor and lend 'em a hand, eh? Find 'em south of here.", sourceObjective = "Speak to Kalen Trueshot at Trueshot Point in Stonetalon Mountains.", completion = "<Kalen sighs.>\n\nWe use guns just fine, friend. CANNONS, on the other hand, I take issue with...", sourceObjectiveStatus = "unverified-source-field" }
quests[25614] = { id = 25614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Way Down is in a Body Bag", description = "The skies are swarming with heavily armored orcs on the backs of even more heavily armored wind riders. Our best efforts to bring them down have thus far proven fruitless. Our arrows usually just bounce off of those foul creatures. If we do happen to take one down the orcs deploy their goblin parachutes and safely land on the ground below.\n\nI need you to use Gnombus's sniper cannons and blow up the Warsong wind riders and then blow up the parachuting orcs.\n\nThe only way down is in a body bag.", sourceObjective = "Kill 8 Warsong Wing Commanders.", progress = "We can't get across the pass safely without the wind riders being taken out first.", completion = "Excellent work, {name}. The gnome technology, while somewhat obnoxious, is highly effective. We should now have a clear path to Windshear Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[25615] = { id = 25615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Stardust", description = "Huntress Jalin will be pleased to know that the way to Windshear Hold is now clear. Please return to Stardust Spire and inform her of your success. She will most assuredly have more work for you now that our path is clear.\n\nThank you and good luck, friend.", sourceObjective = "Return to Huntress Jalin at Stardust Spire in Ashenvale.", completion = "With the airways clear our hippogryphs will be able to move into Stonetalon freely. Well done, {name}!\n\nNow on to more pressing matters. \n\nWhat you witnessed at Trueshot Point was a small sampling of the decimation left in the wake of Hellscream's legacy. As Warchief of the Horde, Hellscream has declared Kalimdor as the Horde's sovereign territory. All that would oppose the Horde are destroyed.\n\nWe are Kalimdor's last line of defense. Should we fall, Kalimdor will also fall. The Horde must be stopped!", sourceObjectiveStatus = "unverified-source-field" }
quests[25616] = { id = 25616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellscream's Legacy", description = "Enter Stonetalon Mountains through Talondeep Pass and head towards the smoldering trees. Seek out the Krom'gar incinerators that are destroying the forest and slay as many as you can! Be warned, the incinerators are powerful orcs. Attacking them through conventional means will likely result in your death. Destroy the oil canisters on their backs and they will be devoured by flame!\n\nReport to Sentinel Heliana at Windshear Mine should you succeed. She will have your new orders.", sourceObjective = "Slay 10 Krom'gar Incinerators.", completion = "With the Krom'gar incinerators dealt with, the forest may be allowed to regrow. Only time can heal the wounds left by the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[25617] = { id = 25617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Maw!", description = "Atop the Lightning Ledge, the Twilight's Hammer has erected an enormous flamegate. I do not know where it leads; I know it is not of this realm, and I cannot enter. None of my other followers have returned.\n\nI need you to enter this realm and be my fangs within. Step through the flamegate. If he is still alive, meet with Jordan Olafson inside. He will give you a token that will allow you to use my powers in that realm.\n\nBe bold, {name}. Find out where that flamegate leads, and destroy whatever lies within.", sourceObjective = "Step through the flamegate atop the Lightning Ledge in Mount Hyjal, and speak with Jordan Olafson within.", completion = "Ah, you are the champion Lo'Gosh promised! Your eyes don't deceive you: you have entered the Firelands, an elemental plane of molten stone and fire. We've got our work cut out for us here.\n\nPut aside your differences with the Alliance, there's plenty of danger to go around.\n\nAnd take this: the Fang of Lo'Gosh will allow you to channel the ancient's power here within the Firelands. Use it well!", sourceObjectiveStatus = "unverified-source-field" }
quests[25618] = { id = 25618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Maw!", description = "Atop the Lightning Ledge, the Twilight's Hammer has erected an enormous flamegate. I do not know where it leads; I know it is not of this realm, and I cannot enter. None of my other followers have returned.\n\nI need you to enter this realm and be my fangs within. Step through the flamegate. If he is still alive, meet with Jordan Olafson inside. He will give you a token that will allow you to use my powers in that realm.\n\nBe bold, {name}. Find out where that flamegate leads, and destroy whatever lies within.", sourceObjective = "Step through the flamegate atop the Lightning Ledge in Mount Hyjal, and speak with Jordan Olafson within.", completion = "Ah, you are the champion Goldrinn promised! Your eyes don't deceive you: you have entered the Firelands, an elemental plane of molten stone and fire. We've got our work cut out for us here.\n\nPut aside your differences with the Horde, there's plenty of danger to go around.\n\nAnd take this: the Fang of Goldrinn will allow you to channel the ancient's power here within the Firelands. Use it well!", sourceObjectiveStatus = "unverified-source-field" }
quests[25619] = { id = 25619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reoccupation", description = "There's no shortage of Kvaldir to slaughter. They're obviously still reeling from our assault.  The city has been desolate so long, I doubt they expected any naga to contest them here.\n\nThere have been no reports yet of their leader. I'm sure that culling them further will force the coward to rear his head soon enough.\n\nShall we continue?", sourceObjective = "Kill 10 Kvaldir defenders in the Ruins of Vashj'ir.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", progress = "I had heard tales of the fierceness of these Kvaldir, but so far, the boasts seem empty.", completion = "Hah! It seems you were right. That broken trident is serving you just fine. I suppose I don't get to see you claw anything to death today after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[25620] = { id = 25620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Revered Lady", description = "The Revered Lady has sent word for you. She awaits you at the far end of the temple gardens.\n\nIf you feel the need to mention the heroic exploits of your faithful battle brother, Azjentus, please don't hold back. I won't take your admiration of me as a weakness.\n\nI'll hold you up no longer. The Lady awaits.", sourceObjective = "Speak to Lady Naz'jar at the north end of the Quel'Dormir Gardens.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", completion = "Ah, my battlemaiden, you've come to me. The warrior caste whispers of nothing but your victories on the battlefield, and we've only just begun our assault to take the city.\n\nYou have served me proud thus far. May the Queen favor you that you might continue to do more of the same.", sourceObjectiveStatus = "unverified-source-field" }
quests[25621] = { id = 25621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Test: Gnomecorder", description = "Ze Gnomecorder iz complete! Now ve must test zit!\n\nVenture into Stonetalon Mountains to ze southeast and valk down ze Talondeep Pass until you reach a filzy goblin drill machine. I vill activate ze Gnomecorder ven you reach your destination!", sourceObjective = "Enter Stonetalon Mountains and travel south along the Talondeep Pass until you arrive at a goblin drill machine.", completion = "<The Gnomecorder crackles and pops with static electricity.>\n\nCome in, {name}. Can you hear me? Zis iz Professor Xakxak!\n\n*POP*\n\n*CRACKLE*\n\nPERFECT! Viz ze Gnomecorder I vill be able to direct you about Stonetalon vile staying out of harmz vay!\n\nNow, onto our next order of buziness!", sourceObjectiveStatus = "unverified-source-field" }
quests[25622] = { id = 25622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn, Baby, Burn!", description = "Deze orc incinerators zat burn ze forest carry viz zem powerful veaponry! You must kill zem and take zhere flame thrower. Vonce you have ze flame thrower, search ze forest for varsong stockpilez and use ze flame thrower to burn zem down!\n\nBurn zem all and I vill reward you! Yes, ze Gnomecorder can transport items!\n\nVait! Do you hear zat! I zink zhere iz an orc nearby! Vatchout!", sourceObjective = "Obtain a Warsong Flame Thrower from a Krom'gar Incinerator and use the Warsong Flame Thrower to destroy 8 Warsong Stockpiles.", completion = "<The Gnomecorder buzzes loudly.>\n\nVonderful! As promised, VOILA, your reward!\n\nNow, I have a bit of news that you might find interesting.", sourceObjectiveStatus = "unverified-source-field" }
quests[25623] = { id = 25623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Maw!", description = "{name}, there you are! Goldrinn has a mission that only his champion can accomplish. Atop the Lightning Ledge, Twilight's Hammer has erected a flamegate. We don't know where it leads, but Goldrinn can't enter. The ancient needs you to be his fangs.\n\nStep into the flamegate and talk to Jordan Olafson when you get inside. He'll give you a token to allow you to use Goldrinn's power in that realm. Find out where the flamegate leads!", sourceObjective = "Step through the flamegate atop the Lightning Ledge in Mount Hyjal, and speak with Jordan Olafson within.", completion = "Ah, you are the champion Goldrinn promised! Your eyes don't deceive you: you have entered the Firelands, an elemental plane of molten stone and fire. We've got our work cut out for us here.\n\nPut aside your differences with the Horde, there's plenty of danger to go around.\n\nAnd take this: the Fang of Goldrinn will allow you to channel the ancient's power here within the Firelands. Use it well!", sourceObjectiveStatus = "unverified-source-field" }
quests[25624] = { id = 25624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Maw!", description = "{name}! Lo'Gosh needs you. Atop the Lightning Ledge, Twilight's Hammer has erected a flamegate. We don't know where it leads, but nobody who's gone through has returned. You are to venture inside and be the fangs of Lo'Gosh within.\n\nStep into the flamegate and talk to Jordan Olafson when you get inside. He'll give you a token to allow you to use Lo'Gosh's power inside that realm. Find out where the flamegate leads!", sourceObjective = "Step through the flamegate atop the Lightning Ledge in Mount Hyjal, and speak with Jordan Olafson within.", completion = "Ah, you are the champion Lo'Gosh promised! Your eyes don't deceive you: you have entered the Firelands, an elemental plane of molten stone and fire. We've got our work cut out for us here.\n\nPut aside your differences with the Alliance, there's plenty of danger to go around.\n\nAnd take this: the Fang of Lo'Gosh will allow you to channel the ancient's power here within the Firelands. Use it well!", sourceObjectiveStatus = "unverified-source-field" }
quests[25626] = { id = 25626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of the Past: Rise from the Deep", description = "What you told me of the naga before has been plaguing my mind. Who are these allies they're summoning? Do they really think they can defeat the Tidehunter?\n\nEscaping this cave brings a degree of relief, but our purpose here remains. I'm hoping you will be willing to seek answers from the Battlemaiden one last time.\n\nThere's only one place that I can think of where they would have taken the artifact - the temple atop the ruins. It's sure to be well guarded. Proceed carefully.", sourceObjective = "Witness the concluding story of the Battlemaiden by using her broken blade somewhere in the Temple of Quel'Dormir.", completion = "Minions of the Old God? Two very potent foes have joined forces then. Their hope to defeat the Tidehunter may not be so foolish after all.\n\n{name}, we can't let that happen. If Azshara defeats the Tidehunter and takes his power for herself, I'm not sure any number of us could ever hope to oppose her on the seas.\n\nThe first step is clear at least - we need to hunt down the fiend that destroyed our ships. The navy was confident enough to bring in a new fleet, perhaps they have a plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[25627] = { id = 25627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two-Tusk Takedown", description = "This treasure's all fake, but it's not like those den whompers are going to know the difference. Stupid ogres!\n\nHere's the plan... you head into the Admiral's Den and spread all of this \"treasure\" around to any ogres that get in your way. Then all you have to do is confront Tony Two-Tusk.\n\nYou'll have the key to the cage in no-time!", sourceObjective = "Obtain the Rusted Cage Key.", progress = "What's going on? You gonna get me out of here?", completion = "Yeah, yeah, yeah... I'm sure that your little adventure into the cave was very interesting.\n\nHow about we talk about it over drinks back on the Speedbarge once you get me out of this cage?", sourceObjectiveStatus = "unverified-source-field" }
quests[25628] = { id = 25628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two-Tusk Takedown", description = "This treasure's all fake, but it's not like those den whompers are going to know the difference. Stupid ogres!\n\nHere's the plan... you head into the Admiral's Den and spread all of this \"treasure\" around to any ogres that get in your way. Then all you have to do is confront Tony Two-Tusk.\n\nYou'll have the key to the cage in no-time!", sourceObjective = "Obtain the Rusted Cage Key.", progress = "What's going on? You gonna get me out of here?", completion = "Yeah, yeah, yeah... I'm sure that your little adventure into the cave was very interesting.\n\nHow about we talk about it over drinks back on the Speedbarge once you get me out of this cage?", sourceObjectiveStatus = "unverified-source-field" }
quests[25629] = { id = 25629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Her Lady's Hand", description = "Battlemaiden!\n\nFind my Honor Guard upon the field of battle and relieve them of their foes. I need them to return to guard the priestesses immediately!\n\nI will hold the entrance. Be swift!", sourceObjective = "Defeat the opponents of 8 Naz'jar Honor Guard on the field of battle and deliver their new orders.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", progress = "I dispatched my Honor Guard when the fighting broke out. They are better equipped to deal with the chaos of this kind of battle, and I am hardly in need of their aid.", completion = "Well done, Battlemaiden.\n\nI will attend to the eastern bridge. I need you to attend to the temple itself. The ritual must not be interrupted.", sourceObjectiveStatus = "unverified-source-field" }
quests[25630] = { id = 25630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fires of Mount Hyjal", description = "Do you see it, {name}? From the ridge southwest of here... plumes of black smoke curling into the sky.\n\nMount Hyjal is burning.\n\nIf the fires have raced this far up the mountain, surely they threaten the Grove of Aessina and all of our forces there. Can you investigate?\n\nSpeak with Laina Nightsky near the Grove of Aessina. Last I heard, she was fighting off the assault.", sourceObjective = "Speak with Laina Nightsky near the Grove of Aessina in Hyjal.", completion = "Can this wait, {class}? The battle is not going well.\n\nOh, you're here to help. I hope you don't mind a little heat...", sourceObjectiveStatus = "unverified-source-field" }
quests[25637] = { id = 25637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Fathom-Lord's Call", description = "Fathom-Lord Zin'jatar has sent word that the Kvaldir leader has shown himself. I would like you to make your way to him at the far end of the terrace above us, on the middle level of the ruins: Nar'shola Terrace.\n\nKill any Kvaldir that stand in your path on that terrace. We want the echoes of this defeat to ring in their minds so that they will dare not return to threaten our purpose here.\n\nYour devotion does not go unnoticed, my battlemaiden. Go knowing that you have my blessing.", sourceObjective = "Kill 16 Kvaldir on Nar'shola Terrace, the middle level of the ruins.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", completion = "It is good of you to join me, Battlemaiden. The echoes of your combat graced your approach. It was a beautiful sound to behold.", sourceObjectiveStatus = "unverified-source-field" }
quests[25638] = { id = 25638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Plea", description = "The note in this bottle is soaked through, but still legible.\n\nIn it, the author claims to have escaped from some sort of undersea naga prison.\n\nHe is clearly in fear for his life, and you can't help but wonder if it might be one of your recently abducted shipmates.\n\nAt a loss as to how to locate the escapee, you determine to share the find with Erunak.", sourceObjective = "Take the Soggy Note to Erunak at Shallow's End.\n\nProvided item:", completion = "If he still lives, I may be able to locate this poor soul.", sourceObjectiveStatus = "unverified-source-field" }
quests[25640] = { id = 25640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombs Away: Windshear Mine!", description = "Ve have discovered ze vhereabouts of ze gigantic goblin bomb zat you discovered at Silvervind Refuge.\n\nYou remember Boog? Ze gnome you rescued from ze orcish vagon of agony? Vell, he and Minx have tracked ze bomb down to Windshear Mine. Go zhere immediately, {name}! Zey'll be expecting you.", sourceObjective = "Report to Boog the \"Gear Whisperer\" at Windshear Mine in Stonetalon Mountains.", completion = "Good to see you again, {name}. Thanks for the rescue in Ashenvale. Damn shame about all the gnomes we lost.\n\nYou ready to get down to business?", sourceObjectiveStatus = "unverified-source-field" }
quests[25641] = { id = 25641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flow of Muisek", description = "I've done all I can for you. Muisek stronger than the hippogryph just isn't within my power to work with yet, so I won't make you deal with the disaster that could bring.\n\nBut while you've been busy, I've fully readied the hippogryph muisek. Take it to my master, Witch Doctor Uzer'i in Camp Mojache. He can create powerful weapons with it, and hopefully he'll be impressed by what I've done.", sourceObjective = "Deliver the Muisek Vessel to Witch Doctor Uzer'i at Camp Mojache in Feralas.", progress = "I sense something familiar in your presence...", completion = "Well done indeed... I'd expect nothing less from my own daughter. She'll make a fine witch doctor someday.", sourceObjectiveStatus = "unverified-source-field" }
quests[25642] = { id = 25642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Look Them in the Eyes", description = "Keep your head down, {name}. No need to draw unwanted attention.\n\nLooks like the orcs are piling that balloon up with some type of ore from the mine. Get in there and take the ore from the orcs. Bring me back whatever you manage to grab and I'll ship it off to the professor for examination.\n\nBefore you go, a word of advice: you can avoid the Krom'gar pretty easily in there as (1) they're dumb as dirt and (2) they can't see anything if they're carrying ore. Of course, you need to kill them to get their ore.", sourceObjective = "Collect 10 Azure Iron Ore samples.", progress = "Get me those ore samples!", completion = "Not too much trouble, I hope. With these samples we should be able to figure out what they plan to do with the ore and the big bomb.", sourceObjectiveStatus = "unverified-source-field" }
quests[25643] = { id = 25643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkmist Ruins", description = "I have been beset by visions, {class}. Visions of an icon of great power falling into sinister hands. I see an amulet, held by the ancient elves...sitting forgotten while its surroundings turn to ruins, until it is captured by demons through treachery and malice.\n\nEvery night, these sights flow through my dreams. The spirits are warning us. I am too old, and the camp's braves too occupied with guarding us. I must beseech you to follow my visions to the south, to the Darkmist Ruins, and seek out the amulet.", sourceObjective = "Search the Darkmist Ruins for the amulet Sage Palerunner described.", completion = "<As you reach towards the pedestal, you find it empty. A chill fills the room, and you hear a faint voice...>", sourceObjectiveStatus = "unverified-source-field" }
quests[25644] = { id = 25644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Egg", description = "The egg is unlike any that you've seen before.  Its translucent shell appears to bend the light around it.\n\nAccompanying it, you find a note describing the arrival of a fertile broodmother at the Ascendant's Rise.\n\nPerhaps you should show this to Aronus.", sourceObjective = "Take the Pure Twilight Egg to Aronus at the Gates of Sothann in Hyjal.\n\nProvided item:", completion = "You were right to come to me with this, {name}.  This represents a great threat to us if we do not act swiftly and boldly.", sourceObjectiveStatus = "unverified-source-field" }
quests[25645] = { id = 25645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Sage Palerunner", description = "The soft glow from the pedestal brightens, and you can see a simple chain left behind. This must be the amulet Sage Palerunner sent you here for...", sourceObjective = "Bring the Darkmist Amulet to Sage Palerunner.", progress = "You've returned. What have you found?", completion = "I am a fool...I was misled. This is nothing more than a rusted trinket, and my visions have no doubt been fulfilled.\n\nForgive me, {name}. But should you meet this demoness again, I pray you will triumph over her as you did Verinias.", sourceObjectiveStatus = "unverified-source-field" }
quests[25646] = { id = 25646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windshear Mine Cleanup", description = "The Horde has overrun Windshear Mine. I'm not sure what these orcs are hauling out of here or why they're here, but I know that it can't be good. Get in that mine and take out the management. Without goblin overseers, these peons will be even more worthless.\n\nWhile you're inside, keep your eyes peeled for any other information about the Horde operation in the mines.\n\nGood luck!", sourceObjective = "Kill 6 Windshear Overseers.", completion = "Nice job, I could hear their shrill screams from out here. You've turned the whole place on its head!\n\nDid you happen to find any other information about the mining operation?", sourceObjectiveStatus = "unverified-source-field" }
quests[25647] = { id = 25647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illegible Orc Letter", description = "You've discovered a parchment with an impressive looking Horde seal imprinted upon its page. Unfortunately, the rest of the document is completely illegible as it is in orcish.\n\nTake the letter to Boog. He might know what to do with it!", sourceObjective = "Take the Illegible Orc Letter to Boog the \"Gear Whisperer\" at Windshear Mine in Stonetalon Mountains.", progress = "What have you got there?", completion = "<Boog takes the letter from you and begins to examine it.>\n\nInteresting.\n\n<Boog smells the parchment.>\n\nHrm... Troubling...\n\n<Boog folds the paper in half and looks at you.>\n\nCan't understand a damn thing written here - if that is writing. Could just be toilet paper. Sure smells like it.", sourceObjectiveStatus = "unverified-source-field" }
quests[25648] = { id = 25648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beyond Durotar", description = "Hmmph... it looks like your services are being requested elsewhere.  Ag'tor Bloodfist is looking for recruits to assist the Horde's ventures in Azshara, north of Orgrimmar.\n\nI'm sure you still have work to do here in Durotar, and I understand that they'll shortly be asking for your help in the Barrens.  I wouldn't be going anywhere yet if I were you, but if you're itching for some manifest destiny... Azshara awaits.", sourceObjective = "Report to Ag'tor Bloodfist at the Orgrimmar Rear Gate in Azshara.", completion = "Good, you're here.  Welcome to Azshara, the stage for the next act of the Horde's glorious future.  Now get to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[25649] = { id = 25649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minx'll Fix It", description = "The good news is that Minx is fluent in orcish and she's nearby. Head back into the mine and find her. She's probably deeper inside, standing around being useless.\n\nDon't forget the parchment!", sourceObjective = "Take the Illegible Orc Letter to Minx inside the Windshear Mine in Stonetalon Mountains.", progress = "What have you got there?", completion = "<Minx takes the letter from you and begins to read it.>\n\nUh oh...\n\n<Minx smells the parchment.>\n\nDisgusting!\n\n<Minx folds the paper in half and looks at you.>\n\nThe good news is that this isn't toilet paper. The bad news is that the ink on this paper is a mixture of kodo poop and blood. That's not the worst of it, though...", sourceObjectiveStatus = "unverified-source-field" }
quests[25650] = { id = 25650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders from High Command", description = "The letter is actually an order from Horde high command. Someone named Overlord Krom'gar has issued a \"strip job\" on this mine in order to obtain something called azure iron flake. Presumably this flake is obtained from breaking down the ore.\n\nIt gets worse. They plan to mix the azure flake with the explosives sitting inside the huge bomb outside and blow up Windshear Hold.\n\nWe don't have a moment to lose, {name}! Take this translated copy of the letter and return to Boog! He'll know what to do next.", sourceObjective = "Take the Translated Orc Letter to Boog the \"Gear Whisperer\" at Windshear Mine in Stonetalon Mountains.", progress = "Well? What's it say?", completion = "<Beads of sweat roll down Boog's overly large forehead as he reads the translated letter.>\n\nThis is bad. Really, really bad. You have to warn Lord Fallowmere at Windshear Hold.\n\nWhat in the... It's MOVING! The goblin balloon is taking off! We're too late!", sourceObjectiveStatus = "unverified-source-field" }
quests[25651] = { id = 25651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, the Insanity!", description = "So, I've been thinkin'...\n\nIf someone's out-of-their-mind-guano-crazy, do they know it?\n\nCase in point, I coulda swore that I'd collected a barrel of gunpowder from the cannonballs around here, but it's nowhere ta be found.\n\nI distinctly remember lifting the cannonballs from them Gilblins just west of here.\n\nMaybe they're right... maybe I really have lost it.", sourceObjective = "Collect 50 Pilfered Cannonballs from Gurboggle's Ledge and from Gilblin Hoarders. Use the Cannonballs to create a Barrel of Gunpowder.", progress = "You want nuthin' to do with me, {race}.\n\nI'm a touch... screwy.", completion = "My gunpowder!\n\nYou found it! I'm not crazy after all!", sourceObjectiveStatus = "unverified-source-field" }
quests[25652] = { id = 25652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commandeer That Balloon!", description = "We don't have a moment to lose, {name}. You're going to have to commandeer that hot air balloon and stop it!\n\nHow? I have no idea! We don't have time to argue details! Grab onto that rope ladder and climb up! Just start banging on stuff once you're inside!\n\nIf you somehow manage to stop the balloon and survive, report to Lord Fallowmere at Windshear Hold in the west.\n\nGood luck, we're all counting on you. Now if you'll excuse me I'm going to RUN FOR MY LIFE!", sourceObjective = "Ride the Krom'gar Hot Air Balloon and attempt to stop it from destroying Windshear Hold.", completion = "Amazing story, lad. I'd have never believed you had I not seen it with my own eyes. You did enough damage to that balloon to make those fiends pull back! Alas, the threat is far from over. We have only delayed the attack. There is much work to do if we are to stop the Horde from destroying Stonetalon!", sourceObjectiveStatus = "unverified-source-field" }
quests[25653] = { id = 25653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancients are With Us", description = "Nemesis... destroyed.\n\nI feel rejuvenated.\nPowerful.\nAwakened.\n\nTell Ysera my strength is hers.\n\nThe Twilight's Hammer will fall.", sourceObjective = "Return to Ysera at Nordrassil in Mount Hyjal.", completion = "By relieving Tortolla of his final burdens you have acquired for us a formidable ally... and the final piece of the puzzle.\n\nSteel yourself, {name}. The most difficult part of our journey is to begin.\n\nWe will bring the fight to their stronghold.", sourceObjectiveStatus = "unverified-source-field" }
quests[25654] = { id = 25654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Heart", description = "Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. It is her malicious will that leads the harpies to defend their nests among the ruins of our people.\n\nThe harpies can call to her with a horn they carry - blowing it by the Hatetalon stones, in the northern part of the ruins, will summon Edana.\n\nShow no mercy for these foul creatures. Slay her, and bring her dark heart to me.", sourceObjective = "Slay Edana Hatetalon and obtain Edana's Dark Heart.", progress = "We must not tolerate the infestation of our ancestor's ruins by the harpies.", completion = "These lands will finally be free of the foulness of the harpies. I cannot thank you enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[25655] = { id = 25655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wormwing Problem", description = "Skylord Omnuron has been too gentle with the Wormwing harpies. He allows them to share a perch on this mountain just because they're creatures of the air. Well {class}, not all creatures of the air are created equal.\n\nWhen the attacks on Hyjal began, the Wormwing went into a frenzy. They're up there right now, assaulting a sacred shrine they once claimed to revere.\n\nI'm not troubled. Now we have a reason to drive them from Hyjal, don't we?", sourceObjective = "Slay any combination of 10 Wormwing Harpies (either Screechers or Swifttalons).", completion = "<Thisalee nods, contentedly, her eyes sparkling.>\n\nFeels great to be off the leash, doesn't it?", sourceObjectiveStatus = "unverified-source-field" }
quests[25656] = { id = 25656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrambling for Eggs", description = "There's a pattern to these Wormwing attacks. While groups make a showy assault on the shrine itself, others swoop into the nearby nests and make off with eggs from all the flying creatures of Hyjal.\n\nThese animals are under our protection. Before we find out why the Wormwing are doing this, it's up to us to rescue as many eggs as we can from their talons.", sourceObjective = "Gather 8 Hyjal Eggs.", progress = "<Thisalee is cleaning her nails with a dagger. She looks up at you expectantly.>", completion = "Good, that's a start.\n\nThe birds who laid these eggs will never accept them again, so we'll have to raise these birds as orphans in the shrine here. Were Aviana here, she never would've let this travesty happen.\n\nBut, on to business...", sourceObjectiveStatus = "unverified-source-field" }
quests[25657] = { id = 25657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dah, Nunt... Dah, Nunt...", description = "So, seein' as ya been so kind to me, I'm inclined to let you in on a special secret.\n\nI've found the biggest shiney of all, no more than 50 steps from where we're standin'!\n\nOnly one thing stands between you, me, and great fortune - and his name is Gnaws.\n\nDon't fret now - I've got a plan.\n\nGnaws loves his grubs, so I've loaded one up with that gunpowder so as to make like a trap of sorts, ya see?\n\nJust set it floatin' up in the reef. Once the shark is dead, we're rich!", sourceObjective = "Budd wants you to use the Booby-Trapped Bait at the Rusty Harpoon Gun in the Skeletal Reef.", progress = "Well? Is Gnaws dead, {race}?", completion = "Amazing!\n\nYou watch the great white beast swim off into the depths and wonder to yourself if anything could ever take him down...", sourceObjectiveStatus = "unverified-source-field" }
quests[25658] = { id = 25658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Built to Last", description = "My lady, I have a request from the High Priestess that I am to pass along to you. Many of the city's defenses remain from long before it sunk beneath the waves, and some of them are but a trivial task to reactivate, were it not for the countless Kvaldir that stand in our way.\n\nWe are told you are to be fighting on Nar'shola Terrace above us. You would do my lady a great service if you would but touch some of the devices as you pass. Your noble blood should prove more than sufficient to reactivate them.", sourceObjective = "Reactivate 6 Nar'shola Wards on the middle level of the ruins: Narshola Terrace.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", progress = "The High Priestess sends her thanks for agreeing to aid us in our duties.", completion = "The Nar'shola Wards are performing perfectly. I will inform the Mistress of the Tides of your aid immediately.\n\nThank you for your assistance, my lady.", sourceObjectiveStatus = "unverified-source-field" }
quests[25659] = { id = 25659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Soon Forgotten", description = "The Kvaldir leader has shown his rotting, ugly face but a short swim from here, down this hall to our west. We kill him now and the Kvaldir occupation of our once beloved city shall be ended.\n\nBeware Battlemaiden, for he is no weakling. He has many Kvaldir at his command. Some Sira'kess Sea Witches have been dispatched to weaken him during your attack, but they will be interrupted if you let any of his Kvaldir attack them.\n\nShow no mercy, Battlemaiden.", sourceObjective = "Kill Varkul the Unrelenting.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", progress = "Your foe is but a short swim down this hall. Go, and bring death with you.", completion = "<The Kvaldir General crumples to the ground, defeated.>\n\n<With this, the ruins of Vashj'ir have been claimed for Lady Naz'jar. Her ultimate goals remain uncertain, but it is clear that the naga came here with purpose.>\n\n<If only you could continue, you are sure that the answers to defeating the naga lie within this vision, but the Wavespeaker's magics are waning, and you are losing your connection with the Battlemaiden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25660] = { id = 25660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haunted", description = "You think I'm going to just let you go after you killed me like that, mon? No way! I didn't create a piratical mercantile empire out of nothing just to see you bring me down.\n\nYou're going to help me get back to life. Find my ex-wife, Ajamon, on the north side of the Holdfast. Just follow your nose. She'll be wherever the stinky brewing cauldron is.", sourceObjective = "Speak with Ajamon Ghostcaller at the Southsea Holdfast in Thousand Needles.", completion = "What ya be wantin'? Oh no you don't. I can see ya got Tony's spirit with ya, and I want nothin' to do with it!", sourceObjectiveStatus = "unverified-source-field" }
quests[25661] = { id = 25661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With a Little Help...", description = "Fine, I be helpin' ya. He not gettin' outa payin' me alimony that easy! 'Sides, there be the baby he had with me sistah ta take care of!\n\nFirst thing we needin' is the innards of his closest friends. That'd be his cap'ns.\n\nGo down there an' pay the three of them a visit.", sourceObjective = "Collect Evil Dolly's Heart, Seadog Fajardo's Lungs, and Lilly Landlubber's Liver.", progress = "A fresh heart, lungs, an' liver be what we needin'. The ones from his cap'ns will have ta do though they all be likely picked.", completion = "<Ajamon makes a face at the state of the organs.>\n\nThey's gonna have ta do. It not be like he had many friends. Ain't that right, Two-Tusk?", sourceObjectiveStatus = "unverified-source-field" }
quests[25662] = { id = 25662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Our Sisters", description = "Yesterday morning I dispatched a squadron of huntresses on a mission into Windshear Crag to obtain information about Horde operations in Stonetalon. Field intelligence reports that they have all been captured, including their squad leader, Huntress Illiona.\n\nHead east into Windshear Crag and slay the Krom'gar infantry that occupy the crag and take from them their keys to unlock the Horde cages holding our sisters.\n\nDo your best to locate Illiona once you've freed the huntresses.", sourceObjective = "Obtain 5 Horde Cage Keys to free 5 Captured Huntresses.", progress = "My captor holds the key to this cage.", completion = "We don't have much time. To get me out of here you are going to have to take out Warlord Roktrog. He holds the key to this prison.", sourceObjectiveStatus = "unverified-source-field" }
quests[25663] = { id = 25663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Offering for Aviana", description = "Although the guardian of all winged creatures is no longer with us in body, I sometimes hear her voice in the whisper of swaying leaves.\n\n{name}, we ask much of you as you set out to preserve this mountain. Before going on, take a moment to reflect.\n\nTake this offering of nectar to Aviana's burial circle, a circle of stones just outside the main door of the shrine. Perhaps some time alone with Aviana's memory will help sharpen your focus.", sourceObjective = "Use the Sacred Nectar at Aviana's Burial Circle.", progress = "<The spirit fades in and out of your vision, as though here and elsewhere at the same time.>", completion = "<A whispered plea rings within your head.>\n\nTo be born again, but in darkness...\n\nI have been stolen away.\n\n<The spirit appears frantic, but falls silent as her image fades.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25664] = { id = 25664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Prayer and a Wing", description = "A winged visage? Could it be...?\n\n{name}, there's no time to waste. You may have been speaking to Aviana herself, trying to return to us.\n\nI'll need something from Aviana's past to reach out to her. High atop the ridge overlooking this shrine, you'll find a series of huge nests belonging to Blaithe, an ancient bird of prey that was once her consort. For ten thousand years he's been mad with grief.\n\nGo to one of his roosts, and use this call to summon him. Kill Blaithe and bring me one of his feathers.", sourceObjective = "Use the Enormous Bird Call at one of Blaithe's Nests perched atop the Rim of the World. Kill Blaithe and gather one of his Ancient Feathers.", progress = "Don't trouble yourself over Blaithe's condition. Grief robbed that creature of a soul epochs ago. He was but a shell of his former self, a beast of pure rage.", completion = "That was nasty work, {name}, but it had to be done.\n\nAnd if Aviana is truly to be resurrected, then perhaps your actions have enabled Blaithe to someday come back as well?\n\nNow let's see if we can contact our long lost guardian...", sourceObjectiveStatus = "unverified-source-field" }
quests[25665] = { id = 25665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Plea From Beyond", description = "<You can't make sense of the spirit's urgent plea, but maybe Choluna can decipher what's going on here.>\n\n<Speak with Choluna back inside the shrine!>", sourceObjective = "Return to Choluna inside of the Shrine of Aviana in Mount Hyjal.", completion = "Slow down, {class}! You look as though you've seen a ghost...", sourceObjectiveStatus = "unverified-source-field" }
quests[25666] = { id = 25666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting Your Hands Dirty", description = "Make no mistake, {race}, that is one clever shark. You don't survive down here as long as he has without a little extra smarts.\n\nWhat I'm saying is he won't be fooled so easily again. We're going to have to change our approach a bit.\n\nI won't bore you with the details just yet. For now, I need you to collect a bunch of the innards from these giant sea grubs.\n\nThink you can handle that?", sourceObjective = "Collect 5 Grimy Grub Guts from the Giant Sea Grubs near Harrison's Dig.", sourceObjectiveStatus = "unverified-source-field" }
quests[25667] = { id = 25667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Wendigos", description = "The wendigos in the Grizzled Den to the southwest of town have long been a thorn in our side. They're never quite strong enough to threaten Kharanos directly, yet they prey on travelers, mountaineer patrols, and supply convoys.\n\nI'm going to be withdrawing my observers from the Grizzled Den because I need them on the troll front. Would you help my men finish culling the wendigo population? Without strength of numbers, they won't be able to attack us.", sourceObjective = "Kill 10 Wendigos in the Grizzled Den. You may kill Wendigos or Young Wendigos.", completion = "Now that you've dealt with the wendigos, we should be able to focus our efforts on the Frostmane trolls to the east.", sourceObjectiveStatus = "unverified-source-field" }
quests[25668] = { id = 25668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilfered Supplies", description = "With the Frostmanes making trouble to our east, the wendigos have sensed our weakness and grown bolder in their raids. Only one of the four most recent supply wagons has made it here safely. The wendigos made off with the rest, stashing it in the Grizzled Den, a cave southwest of town. If you're willing to go down there and recover the stolen supplies, you would have the gratitude of all the townspeople and the mountaineers defending Kharanos.", sourceObjective = "Retrieve 6 Pilfered Supplies from the Grizzled Den.", progress = "Did you find any of the missing supplies?", completion = "Well done, {name}. The mountaineers will be glad to hear that half-rations are at an end. They'll need all their strength to continue fighting the Frostmanes.", sourceObjectiveStatus = "unverified-source-field" }
quests[25669] = { id = 25669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rumble in the Lumber... Mill", description = "Prepare yourself, {name}! The Warlord comes! Kill him and take his key. Use the key to release me.\n\nShould we make it out of here, report the following to Lord Fallowmere at Windshear Hold:\n\nThe Horde has aborted their plans to destroy Windshear Hold due to the efforts of one of our heroes. They now plan to move the bomb to Battlescar Valley and drop it on our armies battling the Horde at that location.\n\nThey must be stopped!", sourceObjective = "Kill Warlord Roktrog and free Huntress Illiona by using Huntress Illiona's Cage Key.", completion = "A hero thwarted their plans to destroy Windshear Hold, eh? That hero was you, {name}. You are the pride of the Alliance!\n\nIt seems that you have bought us a little bit of time. I must plan for the battle that lies ahead of us. Seek out the other inhabitants of Windshear Hold and lend them your assistance. I will call for you when I am ready to initiate our defensive strategy.", sourceObjectiveStatus = "unverified-source-field" }
quests[25670] = { id = 25670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DUN-dun-DUN-dun-DUN-dun", description = "If ol' Gnaws had heels he'd be on 'em right now.\n\nFortunately for you, I think like a shark.\n\nGnaws is mad as all get out and we're gunna use that to our advantage.\n\nHere, I found this chain while out treasure-huntin'. Use it to tie off to that harpoon gun.\n\nWhen Gnaws sees ya he'll be consumed with rage - that's when we strike!\n\nYou try to finish him off and I'll sneak in there and grab the shiney.\n\nHurry, {class}, before he grows them teeth back!", sourceObjective = "Use Budd's Chain on the Rusty Harpoon Gun in The Skeletal Reef. Fire the Harpoon when Gnaws is in position over the gun.", completion = "This really ain't as bad as it looks...", sourceObjectiveStatus = "unverified-source-field" }
quests[25671] = { id = 25671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning the Horde", description = "The Horde's numbers swell as reinforcements from Ashenvale and Azshara arrive. There is no diplomacy to be had with the beasts. This is Hellscream's Horde and Hellscream's Horde wants our blood! We will not sit idly by and allow them to take our land and kill our people. We must act!\n\nWe must thin the Horde! Consider it your daily responsibility.\n\nVenture forth into Stonetalon Mountains and slay as many of the Horde as you are able. Let them know that the Alliance will not surrender!", sourceObjective = "Slay any 20 soldiers of the Horde in Stonetalon Mountains.", completion = "Good. Their blood is on Hellscream's hands. Send enough of them back to Orgrimmar in a body bag and the populace of the Horde might react.\n\n<Lord Fallowmere laughs.>\n\nWho am I kidding? They're monsters!", sourceObjectiveStatus = "unverified-source-field" }
quests[25672] = { id = 25672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carcass Collection", description = "These organs be a good start, mon, but we still be needin' lotsa other tings. Normally, we'd be gettin' stuff from family now, but dats only me and my sistah's boy, and Tony ain't worth it!\n\nSo, we be substitutin' some stuff. Lotsa carcasses, in fact!\n\nDeep down in the Shimmering Deep, there's tons of dem from when the water came rushin' in. Killed all of dem creatures. Go down there and bring me up some.", sourceObjective = "Collect 10 Creature Carcasses.", progress = "Ya gots to get me lotsa those carcasses, mon! We not be rid of his foolish spirit if ya don't!", completion = "Oh, that's disgustin'!\n\nWe almost there, mon. Just need ta do one more ting!", sourceObjectiveStatus = "unverified-source-field" }
quests[25673] = { id = 25673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Ask Alice", description = "Mr. P is sick, <mister/miss>. Won't you help him? All you have to do is find his hat and batteries and he'll be all better. I'd go get them myself, but I can't leave Mr. P alone!\n\nHis hat was stolen by the meanies in the Venture Co. over at the water wheel and his batteries are hidden around Windshear Crag. You'll just have to look real hard for those!\n\nWould you kindly bring Mr. P's stuff back so he can teach those baddies in the Horde a lesson?", sourceObjective = "Recover the BD-816 War Apparatus, Mechanized Fire, Mechanized Ice and Mechanized Air.", progress = "Mr. P is so sad. We need to make him happy!", completion = "<Alice claps excitedly.>\n\nMr. P you're gonna be ok! Hooray!\n\n<Alice expertly places all of the parts you collected into Big Papa.>\n\nOh, Mr. P! I knew it!", sourceObjectiveStatus = "unverified-source-field" }
quests[25674] = { id = 25674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Futile Pride", description = "This is actually an old orc city... one of the oldest on Azeroth.  That is, it was until the ogres pushed us out.\n\nToday's Horde refuses to be pushed over by ogres.  My troops and I took the town back by force, and the ogres who once lived here now work as my servants.  Now, our real work begins.\n\nYou look strong enough, but I'd like to see some proof.  Kill one of the ogres that still besiege us, and return to me.", sourceObjective = "Kill a Dreadmaul Ambusher in Dreadmaul Hold.", progress = "Is that ogre blood I smell?  It had better be...", completion = "Well done, {race}.  You've proven that you can take down an ogre... no small feat.  Now let's see if you can take down an Alliance iron mine...", sourceObjectiveStatus = "unverified-source-field" }
quests[25675] = { id = 25675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Combat", description = "I saw your handiwork down there, {race}.  How'd you like to hunt some more ogres?\n\nWe only enslaved the ones we could catch.  Most of the strongest ogres still brood in Dreadmaul Post, plotting our demise.  Our guards can handle the scattered ambushers, but we are not yet firmly entrenched, and will buckle quickly under a coordinated attack.\n\nGo south to Dreadmaul Post and send a message, {name}.  Slay the strongest before they get any ideas.", sourceObjective = "Slay 6 Dreadmaul Maulers and 5 Dreadmaul Warlocks.", progress = "The less we have to worry about ogres, the more we can focus on our true mission here.", completion = "You've done well today, {name}.  Not only have you purchased more time before the next ogre attack, but I think you scared some of the captives into working harder.", sourceObjectiveStatus = "unverified-source-field" }
quests[25676] = { id = 25676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heartstrike", description = "We don't have any hope of taking the Nethergarde Mines from the Alliance... at least not yet.  Nethergarde is well-defended, and their supply routes are established and strong.  Our goal, then, is to damage their economy.  We can't take the mine by force, but with surgical strikes we can drastically reduce the mine's efficiency.\n\nI have men creating a distraction outside the mines.  Head east, sneak into the mines, and speak with Rofilian Dane for your assignment.", sourceObjective = "Report to Rofilian Dane at the Nethergarde Mines in the Blasted Lands.", completion = "Finally... another operative shows up.  I hope you're loosened up... it's time to tango, partner.", sourceObjectiveStatus = "unverified-source-field" }
quests[25677] = { id = 25677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's All Mine", description = "All over this cavern you'll find unguarded piles of ore, just waiting to be tampered with.  Our first choice would be to steal the ore, obviously, but that requires mine carts, protection, and labor... three things we just don't have.  So instead, we're just going to ruin this little mining party with a little bit of highly corrosive solvent.\n\nTake this bottle - CAREFULLY - and pour it onto those heaps of ore.  'Cause if we can't have this ore, then neither can they.", sourceObjective = "Use the Concentrated Solvent on 6 Ore Heaps in the Nethergarde Mines.", completion = "There's nothing quite like a big fat kick in the wallet, is there, you Alliance lunkheads?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25678] = { id = 25678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pick Your Fate", description = "It costs the Alliance approximately fifty gold to train a miner, two hundred to train an engineer, and three hundred to train a foreman.  Every Alliance goon that we kill isn't just a military victory... it's a financial one.\n\nNow get down there and destroy their workers!", sourceObjective = "Slay 8 Nethergarde Miners, 3 Nethergarde Engineers, and 3 Nethergarde Foremen.", progress = "Just because you're costing the Alliance hundreds of gold doesn't mean I'm going to pay you hundreds of gold.  So don't even think about asking.", completion = "Excellent work, friend.  I like the way you do business.", sourceObjectiveStatus = "unverified-source-field" }
quests[25679] = { id = 25679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Mountain", description = "The next phase of operations takes place deeper within the mine.  Speak with Tak'arili for your next assignment.  Just follow the mine cart rails to the southeast, and follow the curve around.  You'll see him at the entrance to the mine's upper chamber.\n\nIt's been a pleasure doing business with you, {name}.", sourceObjective = "Report to Tak'arili deeper within the Nethergarde Mines in the Blasted Lands.", completion = "Good, you here already.  Stick around for a bit, little {race}.  We gonna mess with the Alliance.\n\nI love my job, mon.", sourceObjectiveStatus = "unverified-source-field" }
quests[25680] = { id = 25680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Not Us", description = "First things first... it looks like we got ourselves a problem.  These miners down the pathway to the right have been runnin' around like a chickens without they heads on.  My best guess is that they dug too deep and found somethin' nasty... a demon, an elemental, or some kind o' tentacley beast.\n\nTak'arili don't like surprises.  Find out what the problem is and take care of it, then we get ourselves back on track.", sourceObjective = "Find and slay whatever is frightening the miners in the Nethergarde Mines.", progress = "What was it, mon?  You get a close enough look?", completion = "So it was a demon?  Those miners never seen a demon before?  We're in the Blasted Lands, mon!  Demons are everywhere!\n\n<Tak'arili sighs.>\n\nAh well... let's get on to da good stuff, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[25681] = { id = 25681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some People Just Need Killing", description = "The tunnel ahead, headin' west, will take you straight to Chief Prospector Hondo's office.  He's the big cheese around here, and Tak'arili's heard tell that he's a darn fine miner.  That's why he's gotta die.\n\nThere's just one problem: the pathway is completely FILLED with those pesky Nethergarde flunkies.  That's why you gotta disguise yourself.  Hop inside this box here, and sneak down the pathway.  Hopefully you won't draw too much suspicion on your way to da killin'.", sourceObjective = "Slay Chief Prospector Hondo. Use the Inconspicuous Box to disguise yourself along the way.", completion = "Nice work, mon!  Without Hondo, these guys are helpless.  Dis mine'll be ours soon enough!", sourceObjectiveStatus = "unverified-source-field" }
quests[25682] = { id = 25682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Complete", description = "We be done here, mon.  Only thing left to do is send a report to Okrilla.  You doin' anything right now?", sourceObjective = "Deliver the Nethergarde Mine Report to Okrilla at Dreadmaul Hold in the Blasted Lands.", progress = "You've returned, {name}?", completion = "<Okrilla glances over the report.>\n\nImpressive, {name}.  I wouldn't have hidden in that box, but otherwise, you have performed bravely and admirably.  The battle we won today may not win us any immediate spoils, but the damage you've done to the Alliance will last for a long time.", sourceObjectiveStatus = "unverified-source-field" }
quests[25683] = { id = 25683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreadmaul Furnace", description = "I meant what I said, {race}.  You helped me, now I'll pass on what I know.\n\nA demon hunter recently came through here, but only briefly.  He was headed south, speaking of demons.  Normally I'd have slain the night elf on sight, but he didn't seem to be Alliance scum, and anybody who kills demons is useful to me for the time being.\n\nYou should check in with Lynnore and Drazial, a pair of blood mages I sent down that way.  They've camped in the back of an ogre cave.", sourceObjective = "Report to Bloodmage Lynnore in the back of the Dreadmaul Furnace in the Blasted Lands.", completion = "Okrilla sent you?  Okrilla the killa'?\n\n<Lynnore listens to your tale.>\n\nLoramus was his name?  I'm sorry to say that we have not seen your demon hunter... but we have ways of finding him.", sourceObjectiveStatus = "unverified-source-field" }
quests[25684] = { id = 25684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attune the Bloodstone", description = "I admit, we haven't picked the most... convenient of spots to perform our studies, especially for passing adventurers who wish to enter and leave at will.  Our agreement with the ogres is tenuous, and I'm afraid we can't convince them not to attack you when you draw near.\n\nHowever, I can allow you to attune yourself to our bloodstone teleporters.  Simply place your hands on the stone to my right, and you will be teleported outside of the cave.  Then use the stone outside to teleport back!", sourceObjective = "Attune yourself to the Bloodstone Teleporters in the Dreadmaul Furnace.", completion = "Excellent.  Now that that's out of the way...", sourceObjectiveStatus = "unverified-source-field" }
quests[25685] = { id = 25685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Step", description = "To perform the ritual you've requested - and perhaps some more rituals in the near future - we're going to need blood.  The Blasted Lands are filled with every type of reagent we might need for our blood magic... it's just a matter of the correct combination.\n\n<Lynnore quickly confers with Drazial for a moment.>\n\nBasilisks and hyenas, even amounts.  And we're going to need plenty of it.  Head east, to the center of the Blasted Lands.  And don't forget... you can use that teleporter!", sourceObjective = "Obtain 9 vials of Snickerfang Hyena Blood and 9 vials of Redstone Basilisk Blood.", progress = "Ogre blood only takes you so far.  Do you have it?", completion = "<Lynnore eyes the blood hungrily.>\n\nMore than enough, and still warm!  Now, let's get this ritual started, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[25686] = { id = 25686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Ritual", description = "Our goal is to find the demon hunter, Loramus Thalipedes.  Let me know when you are ready to begin the blood ritual, and then stand back.", sourceObjective = "Speak with Bloodmage Lynnore to begin the blood ritual.", progress = "The ritual is not yet complete.", completion = "The blood ritual was a success; I can clearly see where Loramus is right now.  That is, I can see where the pieces of his body lie...", sourceObjectiveStatus = "unverified-source-field" }
quests[25687] = { id = 25687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Just Any Body", description = "Loramus Thalipedes is dead.  Well, let me step back... that's an assumption on my part, but I do know that his body lies in three pieces.\n\n<Lynnore ponders for a moment.>\n\nIf you bring me the pieces, we still have a recourse.  All three pieces are nearby... the Dreadmaul ogres hide them in their caves.  In fact, one of them is in that chest, down the ledge behind me...", sourceObjective = "Find Loramus' Head, Loramus' Torso, and Loramus' Legs.", progress = "Trust me... whatever happened to Loramus, we can fix.  The limits of blood magic are still undefined.", completion = "I see... yes, we can work with this.\n\n<Lynnore looks at the night elf's head.>\n\nLoramus Thalipedes, demon hunter.  I look forward to meeting you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25688] = { id = 25688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Altar of Storms", description = "Up on the bluffs above our comfy cave is a powerful altar.  A powerful DEMONIC altar, guarded by cultists, but powerful nonetheless.  If you can reach it, you can use it to bring Loramus back to us.\n\nThe altar will likely resist your efforts, so you'll have to protect Loramus' body while the ritual completes.  Bring the demon hunter back to me afterwards.", sourceObjective = "Bring Loramus' Body to the Altar of Storms, then protect it while the ritual completes.", completion = "You... you fool!  What have you done?", sourceObjectiveStatus = "unverified-source-field" }
quests[25689] = { id = 25689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time is Short", description = "I was hunting a demon named Razelikh, when his ogre lieutenant Grol assaulted me.  I was caught unaware, and I died... but so did Grol.\n\nRazelikh plans to return to the Blasted Lands and overwhelm the lands with his demons.  Even now, he is preparing to summon his legions to eliminate us.\n\n<The demon hunter quickly draws a rune in the air, then hands it to you.>\n\nDeliver this to Wazzik at the Dark Portal, to the southeast.  He will guide you.  Quickly!  We haven't much time!", sourceObjective = "Deliver the Discordant Rune to Watcher Wazzik at the Dark Portal in the Blasted Lands.", progress = "Do I know you, good {race}?", completion = "What?  LORAMUS?!\n\nOh blast, keep it down, would ya?  If my boss gets word that I worked for Loramus, do you know how quickly I'd be on my rear end?!\n\n<Wazzik takes the rune from you, presses it to his chest, closes his eyes, and nods.>\n\nWell, you weren't lying.  Let's get to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[25690] = { id = 25690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bloodmage's Gotta Eat Too", description = "Contrary to popular belief, blood elf bloodmages do NOT drink blood.  We eat normal food like everybody else - something which can be hard to come by in the recesses of an ogre stronghold.\n\nThe ashmane boars in the central valley of the Blasted Lands are, if nothing else, convenient for eating, as their meat does not require any cooking.  Would you hunt these boars and help us replenish our foodstores?", sourceObjective = "Obtain 5 Ashmane Steaks from Ashmane Boars in the Blasted Lands.", progress = "I'm famished!  If you don't hurry, I might actually resort to drinking our reagents.", completion = "These are perfect, {name}.  Lynnore and I will eat well for the next several days.", sourceObjectiveStatus = "unverified-source-field" }
quests[25691] = { id = 25691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Charred Granite of the Dark Portal", description = "Loramus wants us - er, YOU - to gather granite chips from these chunks of rock around the Dark Portal.  I don't know what he'd want rocks for, but I have my suspicions, and they're not pleasant ones.\n\nUse this pick and look for small outcroppings of rock along the edge of the portal's blast radius.", sourceObjective = "Obtain 24 Charred Granite Chips.", progress = "Keep it down, would ya?", completion = "I hope this is what he needs.  We probably don't have time for you to return and mine any more.", sourceObjectiveStatus = "unverified-source-field" }
quests[25692] = { id = 25692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vile Blood of Demons", description = "Thalipedes wants demon blood.  Personally, the stuff doesn't even seem like blood to me - more like liquid rot - but that's neither here nor there.\n\nLuckily for you, the area around the Dark Portal is crawling with demons.  Infernals, felhounds, felguards... they've all got what you need, in copious, pustulent amounts.", sourceObjective = "Obtain 7 bottles of Vile Demonic Blood.", progress = "Ugh, what's that smell?  Is that you, or the blood?", completion = "There's no doubt about it, you found demon blood.\n\nLoramus' requests aside, I'm sure Dar'toon is thankful for your efforts.  They've been struggling to deal with these demon distractions for some time now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25693] = { id = 25693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enhancing the Stone", description = "<Wazzik finishes packing the materials up in a neatly-wrapped package.>\n\nThat's all that Loramus asked of us.  When you see him, make sure you let him know how much of a help I was.  I fear he will not see my hand in this.", sourceObjective = "Bring Wazzik's Package to Loramus Thalipedes at the Dreadmaul Furnace in the Blasted Lands.", progress = "{class}... you return...", completion = "This is sufficient.  If you see Wazzik again, you may tell him that he performed satisfactorily.  I will get the bloodmages to work on fashioning the stone knife of sealing.  There is no need for questions now.  All will be revealed in time.\n\nWhile they work, I have another task for you to complete.  Actually, make that three tasks.", sourceObjectiveStatus = "unverified-source-field" }
quests[25694] = { id = 25694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protecting Our Rear", description = "The only reason you see me standing aside Alliance soldiers is because our duty outweighs our enmity... however slightly.  We have been charged with protecting the Dark Portal from unauthorized travel, and with the recent cataclysm, we are particularly susceptible to an attack.  We've already heard reports of black dragons in the area...\n\nWith my men focused on their duty, we need someone to keep the area demons in check.  Around the portal you will find three demon lieutenants.  Slay them.", sourceObjective = "Kill Jarroc Torn-wing, Shahandana, and Gomegaz.", progress = "You have not yet killed these demons.  {name}!  Get back to the field!", completion = "Your work is appreciated, soldier.\n\n<The warlord leans in close, and whispers:>\n\n{race}... if you're still interested, I have one more small task for you...", sourceObjectiveStatus = "unverified-source-field" }
quests[25695] = { id = 25695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watching Our Back", description = "<Warlord Dar'toon speaks in hushed tones.>\n\nI have orders from... higher up... that you would be suitable for.  I've seen the Alliance periodically referring to a stack of papers on that barrel over there.  I'd like you to take a look at those papers and find out what it is that they're plotting.  My duty and station prevent me from such a questionable task, but a newcomer like you might be able to slip in unnoticed...", sourceObjective = "Examine the Alliance Plans at the Dark Portal without getting caught.", progress = "Did you get a look at those plans, {name}?", completion = "You're certain nobody saw you?  Good.\n\n<Dar'toon listens to your recount of the information you saw.>\n\nHmph... fairly harmless stuff.  Either the Alliance are foolish enough to NOT be planning something against us... or they're hiding their information better than I expected.  Either way, well done, soldier.", sourceObjectiveStatus = "unverified-source-field" }
quests[25696] = { id = 25696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sunveil Excursion", description = "Oh, right, I received a notification from someone a few days ago.  The Reliquary, was it?  They're looking for someone to... do something...\n\n<The Warlord rifles through some papers.>\n\nAh, here it is!  Yes, Rohan Sunveil of The Reliquary is seeking able-bodied adventurers to assist with an archaeological expedition to the south.\n\nHere, take this with you.  Why don't you go speak with that elf?", sourceObjective = "Report to Rohan Sunveil at the Sunveil Excursion in the Blasted Lands.\n\nProvided item:", completion = "Welcome, traveler.  Thank you for responding to my summons.", sourceObjectiveStatus = "unverified-source-field" }
quests[25697] = { id = 25697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amulet of Allistarj", description = "When my master helped me to take my eyes out, he gave me the gift of sight... a sight much greater than yours, or even of these blood-craving elves.  My sight allows me to see objects of demonic power, such as the Amulet of Allistarj.\n\nAllistarj himself is dead, but he locked his amulet up in a trove inside the Serpent's Coil, to the east.  Along with the other amulets, this relic will give us access to Razelikh's perch.", sourceObjective = "Obtain the Amulet of Allistarj from the Serpent's Coil in the Blasted Lands.", progress = "Allistarj left a piece of himself in that amulet.  Even now, I can sense his evil.", completion = "<Lynnore examines the amulet.>\n\nHe was an archmage, I can feel it.  I will hold the amulet for you while you collect the rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[25698] = { id = 25698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amulet of Sevine", description = "Sevine's amulet is in the hands of a murloc, far to the east, on a shelf that overlooks the Shattershore.  How it ended up in that murloc's possession, I cannot say, but I can state with certainty that you will find it there.\n\nI feel a stronger connection with Sevine than with the rest of Razelikh's servants... possibly because she built the Altar of Storms, upon which you resurrected me.  Bring her Amulet to Lynnore, along with the rest.", sourceObjective = "Obtain the Amulet of Sevine from Salt-Flop near the Shattershore in the Blasted Lands.", progress = "Sevine's amulet... along with the others, we can reach the Rise of the Defiler.", completion = "<Lynnore hefts the amulet.>\n\nA warlock... and a powerful one at that.  I will hold onto this until the time is right.", sourceObjectiveStatus = "unverified-source-field" }
quests[25699] = { id = 25699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amulet of Grol", description = "Grol... the ogre who tore me apart.\n\n<Loramus laughs.>\n\nIt would seem that Grol's body has changed hands several times since we died together, but it no longer rests with the ogres.  His body, along with his amulet of power, is in a wrecked ship off the Shattershore, to the east.  His amulet is the last... once combined, the three will give us access to Razelikh, and therein lies our chance to stop his madness.", sourceObjective = "Obtain Grol's Amulet from the Shattershore in the Blasted Lands.", progress = "The third amulet, from Razelikh's third lieutenant.", completion = "<Lynnore clutches the third amulet.>\n\nHe was a powerful warrior, this one.  I will keep the amulet until Loramus is ready to proceed.", sourceObjectiveStatus = "unverified-source-field" }
quests[25700] = { id = 25700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loramus Thalipedes Awaits", description = "The enchantment on these amulets was not complex.  Together, their power will grant you access to Razelikh, the amulets' creator.\n\nI am prepared to perform the ritual on you and Loramus.  Speak with me when you are both ready.", sourceObjective = "Speak with Bloodmage Lynnore and participate in her ritual.", progress = "Speak with Lynnore, and quickly, friend.  This is but the calm before the storm.", completion = "It would seem that we are prepared to face our demon, {name}.  We have the amulet's blessing, we have the stone knife, and I alone know the demon's true name: Rakh'likh.  Together, this may be enough to defeat the Defiler.", sourceObjectiveStatus = "unverified-source-field" }
quests[25701] = { id = 25701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Are Rakh'likh, Demon", sourceObjective = "Speak with the Deathly Usher north of the Rise of the Defiler. Once atop the Rise, destroy Razelikh's body, then use the Stone Knife of Sealing to imprison his soul.", completion = "I see.  So this was Loramus' plan all along.\n\nI suspected correctly, but I suppose I refused to believe it.  And now, his final instruction for me makes much more sense:\n\nHe asked me to let you choose from one of these.", sourceObjectiveStatus = "unverified-source-field" }
quests[25702] = { id = 25702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home... Gone... Naga...", description = "<The murloc struggles to speak your language.>\n\nRockpool... attacked.  Naga turn, take village, villagers.\n\nSalt-Flop escape, but others do not.  Go south, talk to Chief Neptool.  Maybe he survive.", sourceObjective = "Salt-Flop has asked you to speak with Chief Neptool of the Rockpool murlocs.", completion = "<The murloc spirit looks upon you sadly.>\n\nSalt-Flop did not shame himself by running away.  Look behind me, and see for yourself.\n\nThe Rockpool had no hope against the naga's attack.", sourceObjectiveStatus = "unverified-source-field" }
quests[25703] = { id = 25703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atrocities", description = "<Though his lips do not move, you can feel the murloc chief speaking to you.>\n\nThe Bloodwash naga and the Rockpool murloc have lived among one another for as long as we could remember.  We have always had our differences, but never provoked one another.  Why, then, would they turn on us?\n\n<Neptool looks over his shoulder at his former villagers.>\n\nYou see what they do now?  They enslave us, sacrifice us, force us to fight one another.  I will stop them, {race}... and you will be my weapon.", sourceObjective = "Slay 10 Bloodwash Barbarians and 10 Bloodwash Enchantresses.", progress = "Strike at the naga, {race}!", completion = "You have done well, brave {class}.  I am pleased... but I am not yet satisfied.", sourceObjectiveStatus = "unverified-source-field" }
quests[25704] = { id = 25704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mad Magus", description = "There's only one ting left dat we can do. Ya gotta slay someone with the big mojo in Tony's presence.\n\nNo, not me!\n\nOl' Magus Tirth went crazy when he tried ta stop the waters rushin' in at the Cataclysm. Now he be hauntin' the area just south of the Holdfast.\n\nTake dis soul stick an' use it on his corpse, mon. Then bring Tony back an' we be gettin' him back in his body.\n\nYa can use me spirit portal ta get down there an' back.", sourceObjective = "Extract the soul of Mad Magus Tirth.", progress = "Ya gotta use the stick on Tirth's corpse if ya gonna help, {name}.", completion = "Now we gonna bring Tony Two-Tusk back ta life. You both ready, mon?", sourceObjectiveStatus = "unverified-source-field" }
quests[25705] = { id = 25705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "False Idols", description = "Neptulon the Tidehunter is our god.  He was the god of the Bloodwash, too, but they have turned their back on him, it seems.  They now choose to worship only Azshara, their naga queen.  You will see likenesses of Azshara littered around their settlements, carved out of seastone.\n\n<The murloc spirit eyes your weapon.>\n\nThat weapon will do.  Send it through their Azsh'ir idols.  They need to be reminded that our father Neptulon is the only one who truly rules the seas.", sourceObjective = "Destroy 8 Azsh'ir Idols on the Red Reaches.", completion = "You make an old murloc proud, {race}.\n\nThank you, and may the waves ever lap at your feet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25706] = { id = 25706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neptool's Revenge", description = "No number of naga deaths will bring back the Rockpool tribe, but any amount of revenge will help the spirits of my people rest more easily.\n\nMany of the more powerful Bloodwash have set up a fortress in the caverns to the northwest.  Slay them, in the name of the Rockpool.  The remaining Bloodwash have erected gladiatorial pools and Azsh'ir altars on our beach, where they pit my people against one another and worship their false god.  Slay them, in the name of the Tidehunter.", sourceObjective = "Slay 8 Bloodwash Acolytes, 8 Bloodwash Zealots, 4 Bloodwash Gamblers, and 4 Bloodwash Idolaters.", completion = "The last Rockpool may be taken hostage today and killed tomorrow, landwalker... but they will pass into the underworld knowing that a brave {race} avenged their death.  Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25707] = { id = 25707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Future of the Rockpool", description = "The Rockpool tadpoles left upon this crate appear tired, scared, and nearly dried out.  They need to be taken to the water, and quickly.\n\nPerhaps if you can drag this crate across the beach and into the Forbidden Sea, far off the coast of the Red Reaches, then they will have a chance of escaping, and the Rockpool murlocs may live on...", sourceObjective = "Drag the Abandoned Bloodwash Crate to the Forbidden Sea off the coast of the Red Reaches.", sourceObjectiveStatus = "unverified-source-field" }
quests[25708] = { id = 25708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Fallen Friends", description = "Based on what you're telling me, it sounds like there aren't many survivors... just restless spirits.  The least we can do is give them their rest.\n\n<Enohar takes a long draw off of a mug of black ale.>\n\nHead back to the Shattershore and vanquish the worgen ghosts that still remain.  Doing so should release their spirit from this world and allow them to pass into the next.", sourceObjective = "Kill 13 Drowned Gilneans on the Shattershore to release their spirits.", completion = "<Enohar takes a sip off of a freshly-refilled mug.>\n\nAye, you've done well, lad.  You do the Alliance proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[25709] = { id = 25709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curtail the Darktail", description = "The other thing that concerns me about those shipwrecks is all the vultures that they've attracted.  Knowing how those birds operate, they've already picked the bones clean, but still... we can't allow them to further desecrate the bodies of our friends.\n\nBefore I brewed, I hunted.  Here, take this bow, and more importantly, these arrows.  They've been laced with a little concoction that should give those bonepickers a surprise.", sourceObjective = "Use Enohar's Explosive Arrows to slay 20 Darktail Bonepickers in the Shattershore.", completion = "It's a tragedy, what happened on the Shattershore.  They weren't even soldiers... just people looking for a new home.\n\nI think we've done all we can, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25710] = { id = 25710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minor Distractions", description = "Nethergarde has stood steadfast for years against the demon onslaught that plagues this land.  Our watch is never-ending, our vigilance unfaltering, and our courage bottomless.\n\nWe have held these lands since the portal opened, but now these Horde insects have the insolence to stand in our way!?  We have protected THEM as well as we have protected ourselves!\n\n<Lungertz looks you over.>\n\nLet's see if you've got a hand for combat.  Slay one of the Horde's Okril'lon scouts that nibble at our perimeter.", sourceObjective = "Kill an Okril'lon Scout outside of Nethergarde Keep in the Blasted Lands.", progress = "What's the matter, too scared to fight?\n\nI should have known not to trust an outsider {class} like you.  Best leave Nethergarde's defenses to its own men.", completion = "Hmm... not bad.  You're quicker than many of my men.  Stick around, {name}... I may have use of you yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25711] = { id = 25711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate the Okril'lon", description = "The Horde are a nuisance that we will deal with, but they are proving more difficult than previously expected.  You are to put a stop to this.\n\nTo the west of Nethergarde, the Okril'lon main forces press on our defenses.  They currently hold the Nethergarde Mines, and they mean to move into the supply camps and, eventually, the Keep.  Thin their numbers and delay their advance, {name}.", sourceObjective = "Slay 9 Okril'lon Infantry at the Nethergarde Supply Camp.", progress = "What are you waiting for, {name}?  Get out there and FIGHT!", completion = "You're an excellent asset to the Alliance and the Kirin Tor, {name}.  Well done.\n\nWith time, our forces will retake the mine and press these Horde dogs out of the Blasted Lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[25712] = { id = 25712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nethergarde Reigns", description = "Lungertz is a strong leader, but he is proud.  He understates the pressure that the Horde is really putting on us.  Without our mine... Nethergarde is penniless.\n\nWe need to move the Horde forces from the supply camp NOW, and doing so means killing their commander, Captain Metlek.  He's not a strong leader, and prefers to bark orders from the back lines, but even so, his death might buy us the victory we need.", sourceObjective = "Slay Captain Metlek at the Nethergarde Supply Camp.", completion = "Thank you, {name}.  Thanks to your efforts, I am confident that with time, we will take back the Nethergarde Mine.", sourceObjectiveStatus = "unverified-source-field" }
quests[25713] = { id = 25713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remove Their Arms", description = "Say there... {name}, is it?  I've got a proposition for you which involves explosions.  Interested?\n\nI couldn't help but overhear your conversation with the quartermaster.  You see... I've been working on an explosive device.  It's not very effective against other creatures, but devastating against artillery.  If you're heading back into the field to visit those orcs, find some enemy supplies and give this thing a try.  Who knows... maybe they like explosions too.", sourceObjective = "Use Buttonwillow's Hand Grenade on 8 Okril'lon Weapons Crates in the Nethergarde Supply Camp.\n\nMake sure to use the grenades from afar, or you will be blasted.", progress = "How did it go out there?", completion = "Ahh, the sound of things going boom makes my heart pitter-pat.  You've made this gnome's day, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25714] = { id = 25714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watcher Mahar Ba", description = "It's time for you to visit the Watcher.  He's been in a bit of a mood lately, and I'm not quite sure why.\n\nHead up to the top of the mage tower and check in with him.  I don't have any work for you here, but I'm certain that he will.", sourceObjective = "Report to Watcher Mahar Ba in the mage tower at Nethergarde Keep.", completion = "My associates were correct to send you to me.  I have a problem which may threaten the sanctity of Nethergarde, and I need someone more capable than most.", sourceObjectiveStatus = "unverified-source-field" }
quests[25715] = { id = 25715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Closer Look", description = "We've seen countless ships sail past the shore to the southeast, but most pass by inconspicuously.  Several days ago, however, a powerful storm carried several of the ships to shore and left them wrecked.\n\nI'd bet a pint of Nethergarde Bitter that they were Horde ships if I didn't love Nethergarde Bitter so much.  I can pay you gold, though, if you'll go check out those ships and report back.", sourceObjective = "Scout out the crashed ships on the Shattershore in the Blasted Lands.", completion = "You saw worgen?  That's bad.\n\nWorgen ghosts?  That's even worse.\n\nThose weren't Horde ships... they were Gilnean.  And they must have been headed down to Surwich, at the bottom of the Tainted Forest.  That makes a lot more sense.\n\nWe've got to try to help them, {name}!  The worgen are our allies!", sourceObjectiveStatus = "unverified-source-field" }
quests[25716] = { id = 25716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultists at our Doorstep", description = "You may have already run into some of the Shadowsworn cultists that dwell in the caves just to the southwest of Nethergarde.  They do not impress an immediate danger upon our fortress, but I fear that they are planning something more dreadful than you can imagine.\n\nThe low-ranking members carry spell foci that might hold an answer.  Bring some back to me intact, if you can wrench them from the cultists' hands.", sourceObjective = "Obtain 6 Intact Shadowsworn Spell Foci from Shadowsworn Spellblades and Shadowsworn Occultists in the Blasted Lands.", progress = "The cultists will not part easily with their foci.  Slay them quickly before they suspect our intent.", completion = "Ably done, {name}.  Now we see if my suspicions are correct.", sourceObjectiveStatus = "unverified-source-field" }
quests[25717] = { id = 25717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demons and the Druid", description = "The Reliquary is focused on the acquisition and preservation of magical artifacts.  Our particular excursion is focused on the demonic artifacts that are hidden in what used to be the Tainted Scar.\n\nA worgen druid has taken residence in the scar and is coaxing a forest to grow.  He seems to be failing, however, as the area is still infested with demons.\n\nAnyhow, his forest stands in the way of our excursion, as do these demons.  Slay the tainted ones, then return to me so we might deal with the druid.", sourceObjective = "Kill 5 Doomguard Destroyers, 5 Dreadlord Defilers, 5 Corrupted Darkwood Treants, and 3 Felspore Bog Lords in the Tainted Forest.", progress = "The forest is not yet cleared of the taint, {name}.  Do as I say, and then we may proceed with our mission.", completion = "Thank you, {name}.\n\nI should be a bit more up-front with you.  The demons were a nuisance, but they are not the real problem.  That worgen druid is our problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[25718] = { id = 25718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How Best to Proceed", description = "Your demon-slaying down there bought our scouts enough time to get a good look at that druid.  My intelligence tells me that his name is Marl Wormthorn... a rogue Gilnean druid of substantial power.  He resides in Maldraz, the large, twisted tree at the center of the forest, and is protected from harm by some strange force.  Whether that force is of demonic or natural sources, we have yet to determine.\n\nSpeak with Elijah.  He may have some more information for you.", sourceObjective = "Report to Elijah Dawnflight at the Sunveil Excursion in the Blasted Lands.", completion = "Rohan's sending YOU to slay his druid?  Very well.\n\nYou should know: Marl Wormthorn is as much demon as he is druid.  Even a druid of his power doesn't have a chance against the demonic energies that run so deeply through this land.  That does not, however, make him any less of an obstacle.", sourceObjectiveStatus = "unverified-source-field" }
quests[25719] = { id = 25719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demoniac Vessel", description = "We need a way to get Wormthorn's attention.  Something to break him out of his trance.  Something that's guaranteed to work.\n\nThe few types of wildlife that managed to make a foothold in the Tainted Forest are, without a doubt, affected by the land's latent energies.  Your task is to collect their body parts and find a way to combine them into a vessel.  If Wormthorn's trance is druidic, or even if it is demonic, a large enough vessel of tainted animal flesh should be able to break it.", sourceObjective = "Kill the Tainted Black Bears, Tainted Nightstalkers, and Tainted Screechers in the Tainted Forest, and try to assemble their parts into a Demoniac Vessel.", progress = "Dawnflight's plan is a good one.  Do you have the vessel, {name}?", completion = "Brilliantly done, {name}.  We have what we need to break the worgen's trance.", sourceObjectiveStatus = "unverified-source-field" }
quests[25720] = { id = 25720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Downfall of Marl Wormthorn", description = "Wormthorn's unnatural forest threatens our excursion's progress.  His trees' roots break our picks, his moss grows over our excavation sites, and his animals attack my men.  When it comes to digging, I'll take a demon-infested wasteland over a forest any day.\n\nTake the demoniac vessel and use it on Marl Wormthorn to pull him from his trance.  Return to me when he is no more.", sourceObjective = "Kill Marl Wormthorn at Maldraz in the Blasted Lands. You can use the Demoniac Vessel to pull him out of his trance.", completion = "Hopefully, with this druid out of the picture, we can get back to our digging.  The world is full of powerful artifacts, {name}.  You just need to be willing to do what it takes to get to them.\n\nFeel free to take one of these.  The Reliquary is always happy to share some of its trove with fellow members of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[25721] = { id = 25721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight the Flood", description = "I'm here because Muradin himself knew that this survey needed someone to keep these buffoons on their toes. They're all too scared of the wildlife to do a thing! If I'm to get them off their duffs, I'm going to need some cleanup done.\n\nWe've got an elemental problem, first off. The flood did such a number here that the water itself's gone hysterical.\n\nI bet you've never slapped the sense into an entire lake before, but I'm askin' it of you now. Whallop those elementals but good for me.", sourceObjective = "Kill 10 Flood Elementals.", completion = "Well I'll be. There's someone around here that isn't a disgrace to Magni, bless his poor gravelly heart.\n\nJust for that, you get first crack at the ale, lad. But don't let it get to your bloody head! We've got more gorram work to do, and I won't tolerate you lettin' up early!", sourceObjectiveStatus = "unverified-source-field" }
quests[25722] = { id = 25722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sedimentary, My Dear", description = "The destruction of the Stonewrought Dam was no small thing, <lad/lass>. We're here to find out just how bad the damage is. A mighty load of water's rampaged through here, and if it's disturbed the earth too far, we could be in for worse later on.\n\nWe can tell a lot from studying the sediment of the flooded area. I need as many soil samples as I can get, so if you could head out there and collect some more, I'd much appreciate it.", sourceObjective = "Collect 8 Flood Sediment Samples.", progress = "Let's see the sediment, then.", completion = "Ah, well. The good news is, these will do perfectly. The bad news is I can tell they're the wrong color for topsoil here, even drunk as I am.\n\nThat means things aren't looking good for the area, {name}. But we've got more tests to run before we hang up the towel.", sourceObjectiveStatus = "unverified-source-field" }
quests[25723] = { id = 25723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thresh Out of Luck", description = "The local wildlife's all messed up from the flood, it seems. This fen used to be full of crocolisks, but I haven't spotted a single one.\n\nWhat I have spotted are threshadons. Never used to be any here, so the flood must've swept them all right out of Loch Modan.\n\nLucky for us, because they're tastier than crocolisks, and I'm running low on provisions. Bring me back some threshadon meat for the camp, and I'll gladly pay you for it.", sourceObjective = "Collect 8 Threshadon Chunks from Displaced Threshadons.", progress = "Are they meaty ones? Let's have a look.", completion = "Lovely. These'll fry up nice, and the camp'll be spared a week of mushroom biscuits.", sourceObjectiveStatus = "unverified-source-field" }
quests[25724] = { id = 25724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmane Aggression", description = "The cataclysm has thrown the balance of power in Dun Morogh into question, {name}. Without warning, a wave of troggs emerged from the caves near Gnomeregan and overran the Frostmane trolls. The trolls have been migrating east ever since.\n\nThere has always been a Frostmane presence up on Shimmer Ridge, to the northwest, but with the migration, the trolls now surround us. We can't allow the trolls to use this position to their advantage. While my men hold the line in the east, strike against Shimmer Ridge.", sourceObjective = "Kill 5 Frostmane Seers and 7 Frostmane Snowstriders on Shimmer Ridge", completion = "We should be able to focus our efforts on the rest of the trolls to the east, but there's still the matter of the wendigos in the Grizzled Den.", sourceObjectiveStatus = "unverified-source-field" }
quests[25725] = { id = 25725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fenbush Berries", description = "We're good on provisions, but we're in need of some medicine. Half the camp's fiercely hung over, and a remedy's in order.\n\nLuckily, I know a good folk remedy taught to me by my dear old mum. We just need some local ingredients.\n\nGather me some fenbush berries, if you would. They keep to where there's water and shade, so look along the shore and near other plants.", sourceObjective = "Collect 15 Handfuls of Fenberries.", progress = "How much've you got?", completion = "These'll do nicely. I'll have the lads back on their feet as soon as I make these somewhat edible.", sourceObjectiveStatus = "unverified-source-field" }
quests[25726] = { id = 25726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dumpy Job", description = "Alright, I need you to help me find my dumpy level.\n\nWhat's that look for? That's right! I said my dumpy level! It's a piece of significant surveying equipment!\n\nI didn't name the bloody thing, alright? Go look it up! All I did was leave it on a rock long enough for one of those horrible oozes to swallow it up. The place is crawling with 'em, but one of them should still have it inside.", sourceObjective = "Obtain a Dumpy Level from a Silty Ooze.", progress = "Did you find the dumpy?", completion = "Oh good, it's undamaged! Thanks a lot.\n\nYou ah, you might want to wipe yourself off a bit there.", sourceObjectiveStatus = "unverified-source-field" }
quests[25727] = { id = 25727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drungeld Glowerglare", description = "The Dark Iron clan is up to no good out here. And if that surprises you, you're thicker than the addled blotters over in that tent. Muradin may pay lip service to those sooty cretins back in Ironforge, but out here all bets are off.\n\nWe had a raid against the camp last night, and one raid is too many. Their leader's a stout fellow by the name of Glowerglare, and he's hiding in the cave on the south bank of the river.\n\nBring me Glowerglare's beard as proof he's no longer a threat to us and Ironforge.", sourceObjective = "Kill Drungeld Glowerglare and take his beard.", progress = "Let's see it, then.", completion = "Good riddance to bad rubbish! I'll burn the foul thing later so it doesn't stink up the camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[25728] = { id = 25728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mr. P's Wild Ride", description = "Now Mr. P just needs an angel to help him navigate. Will you be that angel, <mister/miss>? With you helping we can go out into the crag and kill bunches and bunches of Horde! Waddya say? Come on, <mister/miss>! PRETTY PLEASE WITH SUGAR ON TOP?\n\nIf we kill enough Horde, Mr. Fallowmere will buy us all ice cream!", sourceObjective = "Kill 20 Goblin Technicians and 5 Goblin Harvesters.", completion = "<Lord Fallowmere coughs.>\n\nThis is awkward...\n\nGood job out there with the robot. You caught me a little off guard. I didn't realize the little girl was so...\n\n<Lord Fallowmere points to his temple and twirls his finger around.>\n\nSpecial...\n\nWell, whatever gets the job done, right? Am I right?\n\nProbably.\n\nHave some ice cream.", sourceObjectiveStatus = "unverified-source-field" }
quests[25729] = { id = 25729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerenzo the Traitor", description = "<The Gnomecorder comes to life with a loud buzz.>\n\nCome in, {name}! Are you zhere? I have noted on ze map that you are near ze Cragpool Lake vater vheel, is that correct?\n\nIt vould appear that ze Venture Co. has holed up at ze vheel. Have a look around vhile you are up zhere. If you happen to zee a traitorous gnome by ze name of Gerenzo Wrenchwhistle, put your boot firmly up his keester for me and for Gnomeregan! I vill pay handsomely!", sourceObjective = "Kill Gerenzo Wrenchwhistle.", completion = "<The Gnomecorder buzzes loudly.>\n\nVonderful! That's von more name I can scratch off of my list!\n\nI vill be in touch.\n\nXakxak, out!", sourceObjectiveStatus = "unverified-source-field" }
quests[25730] = { id = 25730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "BEWARE OF CRAGJAW!", description = "By order of people not wanting to get themselves devoured whole by a really huge fish, Cragpool Lake is OFF-LIMITS! Someone decided to up and put a huge, dwarf-eating fish in the lake.\n\nIt is strongly recommended that you stay out, however, if you are the heroic type and have a few friends around, do us all a favor and kill the damned thing! Maybe I can get some fishing done then, eh?\n\nIf you manage to actually do it, meet me back at Windshear Hold for a reward.\n\n-Ol' Irongoat", sourceObjective = "Kill Cragjaw and take Cragjaw's Huge Tooth.", progress = "You kill the beast?", completion = "Well I'll be a monkey's uncle. You actually got the beast, eh? Well, a deal's a deal! Here's your reward!", sourceObjectiveStatus = "unverified-source-field" }
quests[25731] = { id = 25731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bird in Hand", description = "It's time to get to the bottom of this. We need to interrogate the matron of these beasts, Marion Wormwing. We'll capture her alive. Here's the plan:\n\nThe harpies communicate across the ridge using a series of signal fires. If we extinguish one, Marion is sure to come investigate.\n\nYou fight her as a distraction while I sneak up behind and grab her. I'll leave the questioning to you. Let's get her, {name}!", sourceObjective = "Extinguish a Harpy Signal Fire to get the attention of Marion Wormwing. Fight her until Thisalee subdues her, then question the harpy matron.", progress = "Marion used to visit the shrine here. Skylord Omnuron tried to give the harpies the benefit of the doubt, but I never trusted her.", completion = "So the harpies are tools of some sort of dragon - \"Sethria.\"\n\nBut what are the dragons doing to those eggs? And what's this 'special' egg that Sethria wanted so badly?\n\nThis is beyond me, {name}. I've given a report to Skylord Omnuron - he'll know what to do next.", sourceObjectiveStatus = "unverified-source-field" }
quests[25732] = { id = 25732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bone to Pick", description = "We did it!\n\nGnaws is down, and I have our shiney!\n\nThat's good news.\n\nDarn shiney is cursed treasure - makes everyone who touches it a skeleton.\n\nThat's bad news.\n\nThese cursed pirates say the Gilblin King has the secret to remove the hex.\n\nThat's good news.\n\nI can't step foot outside the reef or I'll be cursed forever.\n\nThat's bad news.", sourceObjective = "Budd wants you to collect the Pewter Pounder from King Gurboggle at Gurboggle's Ledge.", progress = "So, {race}...\n\nYou gunna remove this curse, or what?", completion = "This is it?\n\nHow is this gunna remove - wait a minute...", sourceObjectiveStatus = "unverified-source-field" }
quests[25733] = { id = 25733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Out Of Here, Stalkers", description = "Thelgen Rock's an important site here. We need to use it to study the bedrock formations an' such.\n\nOf course, it can't be that easy, so Thelgen Rock's also full of giant cave stalkers. Big as a dwarf and twice as hungry. Like I said, these fancy-lads are researchers, not warriors, so if I want them to get anything done you're gonna have to help me clear the filthy bugs out.\n\nKill as many of the blighters as you can and I'll make it worth your while, {name}.", sourceObjective = "Kill 7 Cave Stalkers and 7 Leech Stalkers.", completion = "Good job. I wouldn't be surprised if the horrid things had eggs in there somewhere, but it'll do for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25734] = { id = 25734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down In Thelgen Rock", description = "I'm feeling slightly less wobbly now, so I'm going to start setting up the level for my final measurements here. There's one last thing I need from you.\n\nThere's a seismograph set up deep within Thelgen Rock to record any movements in the earth. If things have been continuing to shift since the cataclysm, this'll tell us.\n\nThe seismograph's at the very bottom of the cave; find it and bring the record it's created back to me.", sourceObjective = "Retrieve the Thelgen Seismic Record from Thelgen Rock.", progress = "Let's see what we've got, aye?", completion = "Wonderful, lad. This should be all we need. Let's have a look.", sourceObjectiveStatus = "unverified-source-field" }
quests[25735] = { id = 25735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incendicite Ore", description = "Thelgen Rock over yonder is something of a natural wonder. It's the only known source of incendicite in the world!\n\nThe stuff's rare, highly sought, and ridiculously explosive. Hit it with a steel mining pick and you'll set off a fireworks show that'll put a room full of goblins to shame.\n\nLuckily, I've developed a spark-proof pick for such tasks. I'll loan it to you if you bring me back some incendicite ore, and I'll split you in on the profits, of course.", sourceObjective = "Collect 8 pieces of Incendicite Ore.", progress = "Well, you look like you're in one piece.", completion = "Glorious! Beautiful stuff, this ore.\n\nGood on you for not droppin' your pick. Last person I sent out let the butt end hit the floor, and that part's not sparkproof.", sourceObjectiveStatus = "unverified-source-field" }
quests[25736] = { id = 25736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Floodsurge Core", description = "This is all that's left of the huge elemental that attacked you: a frothing orb of water that continues to fight your grip.\n\nForba might appreciate seeing proof that you helped stop another threat to the camp.", sourceObjective = "Deliver the Floodsurge Core to Forba Slabchisel.", progress = "Eh? What's that you've got there?", completion = "The thing's still got some fight in it! Amazing!\n\nYou're a tough one, {name}. It's much appreciated. I'd say a reward is in order before you head out.\n\nKeep doin' your best for Ironforge, you hear? And if you ever see my sister, say hello for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[25737] = { id = 25737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tenuous Negotiations", description = "From what I've learned about these water-goblins, this should work.\n\nI've crafted a shark-tooth necklace from the items you scrounged up. Not only is it a shiny trinket, but it's a memento of Gnaws' death. There's no telling how many gilblins were eaten alive by that monster.\n\nOffer the necklace to the gilblin leader. In exchange, I need an artifact called The Pewter Pounder.\n\nAnd be quick about it, kid. I'm already beginning to miss my flesh...", sourceObjective = "Speak to King Gurboggle.", sourceObjectiveStatus = "unverified-source-field" }
quests[25739] = { id = 25739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If the Horde Don't Get You...", description = "<Captain Kosak coughs weakly.>\n\nWas traveling up Webwinder Path, coming from Northwatch Expedition Base Camp in the south. Ambushed. Not by Horde. Spiders. Big, ugly, hairy, nasty spiders.\n\nFought off dozens, maybe hundreds. Lost count. Overtaken by their queen. She took a chunk right out of me. Barely made it out alive. Might be dying.\n\nMore of my men coming. Must provide safe passage. Kill spider queen.\n\n<Captain Kosak passes out.>", sourceObjective = "Kill Queen Silith.", completion = "<Captain Kosak forces a smile at you.>\n\nDon't worry about me. Should be ok now that big hero killed the spider queen.\n\nCan get reinforcements through safely now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25740] = { id = 25740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fact-Finding Mission", description = "The dragon Sethria must be stopped. We know that her roost is south of here, along the southern cliffs of Hyjal, but beyond that we know little else.\n\nI have sent Thisalee on a fact-finding mission to Sethria's Roost. She specifically requested your help - evidently you made quite an impression with the young druid.\n\nMeet Thisalee just beyond the tunnel leading to Sethria's Roost. And remember, this is a fact-finding mission - don't do anything crazy!", sourceObjective = "Report to Thisalee at the entrance to Sethria's Roost in Mount Hyjal.", completion = "Ah, {name}! I was hoping to see you out here.\n\nWhat, Omnuron calls this a 'fact-finding mission?' Bah! Facts are best found on corpses.\n\nLet's do some damage.", sourceObjectiveStatus = "unverified-source-field" }
quests[25741] = { id = 25741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations for the Future", description = "Poisoned travelers are becoming a common occurrence around Windshear Hold. Why just the other day a Northwatch Captain fell prey to the spiders of the Webwinder Hollow. He would have died to the poison had it not been for my anti-venom. Sadly my stock of anti-venom is almost completely depleted.\n\nIf you're heading south towards Webwinder Hollow, would you kindly recover Deepmoss venom sacs for me? You should be able to acquire them from Deepmoss spiders.", sourceObjective = "Collect 10 Deepmoss Venom Sacs.", progress = "Have you recovered the venom sacs I requested?", completion = "This will keep us stocked on anti-venom for the foreseeable future. Thank you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25743] = { id = 25743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decisions, Decisions", description = "This is no magic solution to my curse! It's just a hammer!\n\nI may be crazy, but I'm not stupid.\n\nThere's NO WAY I'm gunna use this to break my shiney - not after all I've gone through to get it.\n\n<Budd pauses in thought for a moment.>\n\nBut that means I'm stuck down here for eternity...\n\nI had just learned to sail, you know.\n\nOhhh... I can't decide.\n\nHere, you take the hammer and I'll just set the shiney down and look the other way.", sourceObjective = "You must use The Pewter Pounder to destroy The Pewter Prophet.", completion = "Oh, what might have been...", sourceObjectiveStatus = "unverified-source-field" }
quests[25744] = { id = 25744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Negotiations", description = "{name}, great job defending the Speedbarge! I've got something else that I need you to help out with.\n\nI've sent Crazzle Sprysprocket and Kravel Koalbeard northeast to negotiate with the centaur survivors. Their Splithoof Heights is dripping with oil!\n\nI figure those smelly half horses won't know what they've got and we'll get the rights to pump up that black gold for a song, but I'd feel better if you took charge of the talks.\n\nWhat do you say?", sourceObjective = "Speak with Crazzle Sprysprocket at the Splithoof Heights in Thousand Needles.", completion = "<Crazzle gets a gleam in his eye.>\n\nI've got Kravel Koalbeard up there talking to one of their chiefs, but now that you're here, we'll have the rights to pump up their oil in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[25745] = { id = 25745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Negotiations", description = "{name}, great job defending the Speedbarge! I've got something else that I need you to help out with.\n\nI've sent Riznek and Trackmaster Zherin northeast to negotiate with the centaur survivors. Their Splithoof Heights is dripping with oil!\n\nI figure those smelly half horses won't know what they've got and we'll get the rights to pump up that black gold for a song, but I'd feel better if you took charge of the talks.\n\nWhat do you say?", sourceObjective = "Speak with Riznek at the Splithoof Heights in Thousand Needles.", completion = "<Riznek gets a gleam in his eye.>\n\nI've got Trackmaster Zherin up there talking to one of their chiefs, but now that you're here, we'll have the rights to pump up their oil in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[25746] = { id = 25746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sethria's Brood", description = "First order of business is to thin the herd here. This place crawls.\n\nLet's start slaughtering these dragonkin and worry about why they're here later.", sourceObjective = "Slay 12 of Sethria's Minions: Any combination of Twilight Dragonkin or Twilight Dragonkin Armorers.", progress = "Have you delivered a message?\n\nBe sure to take flight, too, and hunt Sethria's minions on the other ledges.", completion = "You're good at this.\n\nI like you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25747] = { id = 25747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking Forward", description = "The Admiral used the information you gathered for him to make a forward post under the terrace to our west. He's been preparing there for some kind of attack against the naga.\n\nYou should go to him immediately and inform him of the scope of what you've witnessed. Our force is small, and I fear for our soldiers if we charge in too recklessly.\n\nTake my sea horse. It knows the way.", sourceObjective = "Find and speak to Admiral Dvorek under the southern terrace in the Ruins of Vashj'ir.\n\nUse Wavespeaker Valoren's sea horse to reach the forward post quickly.", completion = "Good to see you again, {class}. I almost thought we'd lost you to the Wavespeaker's fool errand.\n\nDid anything come of it?", sourceObjectiveStatus = "unverified-source-field" }
quests[25748] = { id = 25748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear Goals", description = "I see. The news you bring is grim, but I was not entirely unprepared for such possibilities. Without any effective scouting of naga numbers, I knew our plan was risky, but that's why we established this forward post.\n\nLet me put it to you plainly, {class}. If we do not keep the naga off-balance, they will bring the fight to us. We do not have the structures or the men to mount a defense, so that is not an option.\n\nWe need more time. Can you thin their numbers to the south?", sourceObjective = "Kill 10 of the naga forces building up on the ground level, under the southwestern terrace.", completion = "More naga are amassing to the south than reported too it seems. We shall have to move quickly then.", sourceObjectiveStatus = "unverified-source-field" }
quests[25749] = { id = 25749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Entirely Unprepared", description = "I overheard your conversation with the Admiral. I know what we're doing sounds insane, but we really don't have much choice. There are people back at that cave that are depending on us.\n\nI've stationed lookouts on various ledges in the immediate area. They're burning ammo fast on the scattered naga scouts. Can you bring them more crossbow bolts to buy us some extra time?", sourceObjective = "Deliver 8 Bundles of Crossbow Bolts to Alliance Lookouts positioned on ledges under the southern terrace.", completion = "You are perhaps the most dependable person I've ever met. I wish I could have more men half as thorough as you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25751] = { id = 25751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Properly Inspired", description = "Hello! I've been scrambling, scrambling to prepare for the Admiral's assault. He's got high hopes and high plans to blow all kinds of things sky high! ...or water high? That would do.\n\nBlowing things high takes EXPLOSIVES! I don't have explosives. It's saddening. Very saddening.\n\nI've been properly inspired to improvise though, and the solution has become apparent. The bulbs on the seaweed hanging from the ruins contain a surprisingly volatile gas. Maybe you might gather some for me? Pretty Please?", sourceObjective = "Gather 8 Bloated Kelp Bulbs hanging under the southwestern terrace.", progress = "Tick, tock, tick, tock. Always in such a hurry. No time for innovation. What I wouldn't give for a lab again!", completion = "You are brave indeed! I've seen you battling all manner of murloc, naga, and pointy-toothed fish, but that was nothing! The way you just sling those kelp bulbs under your arm like that is a whole new kind of fearless. BOOM! You could blow up at any second.\n\nYou're my kind of {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25752] = { id = 25752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swift Action", description = "We have everything we need to begin the attack.\n\nIf your claims were correct, you would do well to make sure you cling tight to your mount as we make the attack. Anyone who gets caught in the open water isn't likely to out-swim a naga.\n\nKill as many as you can as we make the attack run and we'll rendezvous on the broken ledge of the terrace above once we've expended our explosives. Hopefully by that point there will be few enough that we can finish them off the old-fashioned way.", sourceObjective = "Speak to Engineer Hexascrub just outside of the building to join the assault, then use your improvised explosives to kill 100 Azsh'ir Soldiers, 20 Azsh'ir Wave Screamers, and 12 Azsh'ir Archaens.", progress = "Speak to Enginner Hexascrub to secure a mount for the assault.", completion = "You did great up there! You devastated their ranks, but there were far more than we accounted for, and most of our men went down out there in the masses of naga.\n\nWe'll need to hold this position as long as possible to buy them time. Hopefully some of them will still make it to the rendezvous.", sourceObjectiveStatus = "unverified-source-field" }
quests[25753] = { id = 25753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen But Not Forgotten", description = "That was a disaster! Most of our men went down to spears before making it anywhere near the rendezvous.\n\nWe're only going to be able to hold this position for so long before the naga overrun us. We need to get out there to the southwest and save as many of the men as we can find - do anything you can.\n\nThey won't last long. Please hurry!", sourceObjective = "Rescue 6 Injured Assault Volunteers.", progress = "These guys aren't in good shape. We may need to retreat sooner than we'd like.", completion = "Thank you. Truly.\n\nWe need to get these men moving as soon as possible. I'll meet you back at the forward post soon, I'm sure.", sourceObjectiveStatus = "unverified-source-field" }
quests[25754] = { id = 25754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gauging Success", description = "Vicious louts... they did a lot of damage with those spears.\n\n<The admiral winces slightly as he clutches a wound on his side.>\n\nWe'll hold here as long as we can for all the men to make it. I need someone to scout their numbers to see how much damage we did.\n\nOne of the biggest groups of them was around the corner on the northwest portion of this round terrace, and the other was a bit farther to the north in the small tunnel, also on this middle level of the ruins.\n\nUp for some scouting?", sourceObjective = "Scout the northwestern portion of the circular terrace and the tunnel under the main stairs to the north. Both locations are on Nar'shola Terrace, the middle level of the ruins.", completion = "Still so many? They must want something very important here to come in such numbers.\n\nI will be honest with you, {name}, because you deserve at least that: I don't know how much hope there is. We will retreat shortly, but we won't be able to defend ourselves when they strike back. We don't have anywhere to run... we're running out of options.\n\nI'm sorry, I should keep such thoughts to myself. Do me a favor and don't mention any of that to the men. I'll figure something out.", sourceObjectiveStatus = "unverified-source-field" }
quests[25755] = { id = 25755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of the Past: The Slaughter of Biel'aran Ridge", description = "Look, I know this is asking a lot during a time like this, but I need you to tear yourself away from this defeat for a moment.\n\nI will tend to these soldiers - you need to find the location of that battle with the Kvaldir General to the west that you told me about. You should be able to glimpse more of the Battlemaiden's experiences from there. I have a strong feeling that the key to defeating these naga will lie with that Battlemaiden.\n\nPlease hurry - I will do everything I can to buy you time.", sourceObjective = "Witness the continuing story of the Battlemaiden by using her broken blade at the site of the Kvaldir General's death.", completion = "You're finished! Just in time. I don't think we could have held them much longer.\n\nAn artifact? Could this be something we can use against the naga? I suppose that would require finding it.\n\nWe may have to attend to more pressing matters first, until an opportunity to pursue this further presents itself.", sourceObjectiveStatus = "unverified-source-field" }
quests[25756] = { id = 25756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Zherin!", description = "If we're going to get those oil drilling rights, we need to know what the Horde is offering. How can we win if we can't do them one better?!\n\nTheir negotiator, Trackmaster Zherin, is up there talking with one of their khans right now. Why don't you head up and persuade him to hand over the Horde's proposal?\n\nYou don't have to kill him... we're not savages! Just rough him up a bit.", sourceObjective = "Obtain the Horde's Proposal.", progress = "Do you have the Horde's proposal? What are they offering for the drilling rights?", completion = "What?! How'd they get that much gold to offer?\n\nWe don't have that kind of money!", sourceObjectiveStatus = "unverified-source-field" }
quests[25757] = { id = 25757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Koalbeard!", description = "If we're going to get those oil drilling rights, we need to know what the Alliance is offering. How can we win if we can't do them one better?!\n\nTheir negotiator, Kravel Koalbeard, is up there talking with one of their khans right now. Why don't you head up and persuade him to hand over the Alliance's proposal?\n\nYou don't have to kill him... we're not savages! Just rough him up a bit.", sourceObjective = "Obtain the Alliance's Proposal.", progress = "Do you have the Alliance's proposal? What are they offering for the drilling rights?", completion = "What?! How'd they get that much gold to offer?\n\nWe don't have that kind of money!", sourceObjectiveStatus = "unverified-source-field" }
quests[25758] = { id = 25758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gap in Their Armor", description = "Do you see what they're doing here? They're affixing armored plates onto the Dragonkin. A page out of Deathwing's book, I suppose.\n\nThose Twilight Juggernauts look like they'll be invincible once they're complete. There's got to be a way around that armor plating!\n\nRun out there and fetch some of the Twilight armor plates that are waiting to be installed. We'll figure out how to beat this.", sourceObjective = "Gather 8 Twilight Armor Plates.", progress = "Did you get a hold of some plates? Did you have to kill anyone to get them?\n\nI hope so.", completion = "Look at these things. Ugh, the runes make my eyes hurt. This one here is meant to sear flesh? Seriously? Ouch! Wait a minute...\n\nThese plates are designed to be riveted directly into flesh. The pain must be unbearable!", sourceObjectiveStatus = "unverified-source-field" }
quests[25760] = { id = 25760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of the Past: The Invasion of Vashj'ir", description = "The shard you recovered looks to be of naga origin. I had hoped to find a strong focal object like this for a spell I've been working on that would allow us to glimpse into the recent past.\n\nI've enchanted the blade, but you'll have to take it to a place where we know its owner was. I want you to travel back to the site where you found it and use the blade.\n\nPerhaps we can uncover more behind what the naga are doing here. Or even better, maybe we'll uncover a weakness that will give us a better chance.", sourceObjective = "Use the Blade of the Naz'jar Battlemaiden at the battle site at the southeast end of the ruins.", completion = "A Battlemaiden? I never heard of such a thing.\n\nThe way you explain it, it sounds like the naga forces are far greater in scope than the Admiral could possibly have realized. We might be able to learn more through the blade if we can find other locations where this Battlemaiden was present, but the information you gave me makes me fear for the admiral and his soldiers. We must warn them.", sourceObjectiveStatus = "unverified-source-field" }
quests[25761] = { id = 25761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disassembly", description = "We have to stop these juggernauts before they're completely encased in armor. Right now they're vulnerable, but only if we pry aside the plates and hack at the marred flesh beneath.\n\nTake my shiv, and jam it between the plates of armored juggernauts to deprive them of their armor.\n\nOnce they break from their trance, you're in for a tough fight - keep prying loose that armor and stop those juggernauts!", sourceObjective = "Use Thisalee's Shiv to awaken and kill 3 Twilight Juggernauts. The shiv can be used multiple times to tear down a Juggernaut's armor.", progress = "Oh good.\n\nYou're still alive.", completion = "That was some fancy bladework, {name}!\n\nThere's one less threat for us to worry about in Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[25762] = { id = 25762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancient Brazier", description = "What do we have here? A {race}? Come to steal our land with your honeyed tongue and promises?\n\nYou do not fool me. I have lived a long time, and I know what dealing with your kind means. But the khans do not listen to their elders like they used to.\n\nSince you are here, I will put you to use. When the waters rushed in, the great water spirit, Aquarian, doused the Ancient Brazier deep inside of Splithoof Hold.\n\nUse this brand to reignite the brazier. Aquarian is sure to come. Bring me the Sacred Flame.", sourceObjective = "Reignite the Ancient Brazier and obtain the Sacred Flame.", progress = "You have the Sacred Flame? Do not speak to me unless you do, {race}!", completion = "You did this favor to ingratiate yourself with me, but I will not sing your praises.\n\nI know what is to come. Where the sea failed, the great air spirit will strike you and your people down for your many transgressions against the elements.\n\nBegone from my sight!", sourceObjectiveStatus = "unverified-source-field" }
quests[25763] = { id = 25763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Codex of Shadows", description = "<This elaborate book contains hundreds of vellum pages bound within a slate cover. It's written in many languages, most unfamiliar. Carefully inked illustrations depict sorcerers or even entire buildings vanishing into curtains of shadow.>\n\n<Many illustrations depict magical artifices like those you see around camp. You suspect the dragon Sethria is trying to keep something hidden. Thisalee will want to hear about this!>", sourceObjective = "Report what you've discovered to Thisalee Crow at Sethria's Roost in Mount Hyjal.", completion = "They're doing what?\n\nThey're cloaking something? Of course - so our aerial scouts can't see anything with our eagle-eyes!", sourceObjectiveStatus = "unverified-source-field" }
quests[25764] = { id = 25764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg Hunt", description = "Skylord Omnuron wants us to find Aviana's Egg, and I can almost guarantee you it's cloaked by one of Sethria's shadow devices.\n\nSearch around the camp for shadow cloak generators and shut those things down until you find the egg.\n\nOnce you've unveiled it, I'll call out to the other druids. Defend that egg until we can carry it off to safety.\n\nGo get that egg, {name}!", sourceObjective = "Disable the Shadow Cloak Generators until you unveil Aviana's Egg. Once the egg is unveiled, defend it until the Druids of the Talon can carry it to safety.", completion = "We did it, {name}! Aviana's Egg should soon be tucked safely in the boughs of her shrine.\n\nDo you think this means she'll really return to us?", sourceObjectiveStatus = "unverified-source-field" }
quests[25765] = { id = 25765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tell 'Em Koko Sent You", description = "Northwatch could really use a powerful {race} like you. We're taking a beating in the Southern Barrens and need your help! Are you interested in lending the Alliance a hand?\n\nThe bomb? Yea, it's a problem, but Stonetalon isn't exactly prime real estate. This place was a dump before the Horde sunk their claws into it!\n\nI'll leave the choice in your hands. If you want to help us out in the Barrens, take my horse, Blue Steel. He's grazing at the crossroads south of here. He'll get you past the orc blockade.", sourceObjective = "Report to Force Commander Valen at the Northwatch Expedition Base Camp in Stonetalon Mountains.", completion = "Kosak sent you, eh? Surprising. I thought for sure that he'd be dead by now.\n\nWell if you made it past the blockade then you definitely have something that we can use.\n\nNow, do you have any news of the Horde? What are they doing? Where are they going? Tell me everything.", sourceObjectiveStatus = "unverified-source-field" }
quests[25766] = { id = 25766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Legacy", description = "The rage of the elements has unearthed a hidden Highborne city in the heart of Stonetalon Mountains.\n\nDirectly southwest of here, through Sishir Canyon, you will find the Ruins of Eldre'thar. Within the ruins lie treasures untouched by mortals for ten thousand years!\n\nTake this device and use it on the Highborne ghosts that inhabit the ruins. It will... put their souls to rest and also collect valuable data which I may peruse at a later date.", sourceObjective = "Use the Highborne Prison to bind 5 Highborne Spirits.", completion = "I assure you, simpleton, the spirits you captured are at rest. Do not let their protests move you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25767] = { id = 25767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capturing Memories", description = "The great cataclysm has unearthed a forgotten Highborne city within Stonetalon Mountains. You must venture southwest to the Ruins of Eldre'thar. Once you are there, search the area for ancient relics. Return the relics to me so that I may study them, {name}.\n\nGo! Lest we keep the arcanist waiting!", sourceObjective = "Collect 8 Eldre'thar Relics.", progress = "Have you recovered the ancient relics?", completion = "Wonderful! Arcanist Valdurian will be most pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[25768] = { id = 25768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombs Away: Mirkfallon Post!", description = "Scout Commander Barus, stationed at Mirkfallon Post, to the northwest, has spotted the Horde bomb. The Krom'gar hot air balloon, with bomb attached, is currently at the new goblin fueling station at Mirkfallon Lake. This might be the opportunity we need to take that thing out once and for all.\n\nGather your things, {name}, and move out! Scout Commander Barus awaits your arrival at Mirkfallon Post.\n\nAnd {name}, your tenacity is a testament to the strength and fortitude of the Alliance!\n\nGlory be unto you!", sourceObjective = "Report to Scout Commander Barus at Mirkfallon Post in Stonetalon Mountains.", completion = "I'm assuming you saw the Krom'gar hot air balloon on your way here. If not, get your eyes checked. It's hovering directly over the oil platform.", sourceObjectiveStatus = "unverified-source-field" }
quests[25769] = { id = 25769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallowmere Beckons", description = "You're still here? What are you waiting for, a personal engraved invitation? Lord Fallowmere beckons, fool! Go to him now!", sourceObjective = "Speak to Lord Fallowmere at Windshear Hold in Stonetalon Mountains.", completion = "Good to see you again, {name}. I have some news from Mirkfallon Lake.", sourceObjectiveStatus = "unverified-source-field" }
quests[25770] = { id = 25770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keg Run", description = "Alright. We need to get this ale to where it's going right away!\n\nIronforge has sent out an expedition of surveyors to check the damage done to the wetlands when the dam burst. Forba Slabchisel's the one leading it...and believe me, you don't want to get on her bad side!\n\nShowing up with an armful of ale will help with that. Go and take this ahead to her, and she might even ask you to stick around for some work.", sourceObjective = "Deliver the Mountaineer's Ale to Forba Slabchisel at Slabchisel's Survey.", progress = "Aye? What've you got for me there?", completion = "Hah! Nice to see those addlebrained mountaineers knew to hand the ale off to a real man to get the job done.\n\nWelcome to my survey. If you're of the mind to help Ironforge by takin' over the intended jobs of some useless, lazy sods that call themselves dwarves, you're in the right place!", sourceObjectiveStatus = "unverified-source-field" }
quests[25771] = { id = 25771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Draenei's Junk...", description = "A shard of glimmering rock sits before you.  You sense that this item would be of value to someone within the Blasted Lands.", sourceObjective = "Return the Imperfect Draenethyst Fragment to Kum'isha the Collector in Blasted Lands.", progress = "Well? Draenethyst?", completion = "Just a shard?  Pfuh!  This gets me nothing!  Take your reward and get out of my sight.\n\nSounds familiar?  It should, because I say it a thousand times per day.\n\nOh how I loathe this world.", sourceObjectiveStatus = "unverified-source-field" }
quests[25772] = { id = 25772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kum'isha's Endeavors", description = "A glimmering sphere sits before you.  You sense that this item would be of great value to someone within the Blasted Lands.", sourceObjective = "Bring the Flawless Draenethyst Sphere to Kum'isha the Collector in Blasted Lands.", progress = "Have you found a flawless draenethyst sphere?", completion = "Simply amazing.  I had doubted that anyone could find another sphere, yet here it is, pulsating in my hands.\n\nWell done, {name}!\n\nShould you find anymore--and I believe this to be an impossibility--return them to me and I shall reward you again.", sourceObjectiveStatus = "unverified-source-field" }
quests[25773] = { id = 25773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Natural Occurrence", description = "This shard is all that is left from the rift that stood here before.  The connection between the shard and the rift is unknown, but perhaps someone more versed in the elements would know more.\n\nSeek out an Earthen Ring Emissary at any capital city.  This could be exactly what they are looking for.", sourceObjective = "Take the Elemental Shard to an Earthen Ring Emissary in Ironforge, Stormwind, Exodar or Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[25774] = { id = 25774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fool's Gold", description = "We definitely DO NOT have the kind of gold that the Horde is offering. {name}, we have to do something or we're not going to be able to get those drilling rights!\n\nWait a minute! There was this report from an underwater survey that we did right after the Cataclysm struck. Something about some gold-looking ore that was pushed up from underground. That's it!\n\nHead west to the old stomping grounds of the centaur, Splithoof Crag and Splithoof Hold, and dig some up.", sourceObjective = "Collect 8 Needles Pyrite Ore Chunks.", progress = "Once you return with enough of that pyrite, we'll give it a once over with a paint brush, pile it all up on a pallet, and send you back up with it to the chieftain.", completion = "Genius! Now, where's that gold paint? I know it's around here somewhere.", sourceObjectiveStatus = "unverified-source-field" }
quests[25775] = { id = 25775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fool's Gold", description = "We definitely DO NOT have the kind of gold that the Alliance is offering. {name}, we have to do something or we're not going to be able to get those drilling rights!\n\nWait a minute! There was this report from an underwater survey that we did right after the Cataclysm struck. Something about some gold-looking ore that was pushed up from underground. That's it!\n\nHead west to the old stomping grounds of the centaur, Splithoof Crag and Splithoof Hold, and dig some up.", sourceObjective = "Collect 8 Needles Pyrite Ore Chunks.", progress = "Once you return with enough of that pyrite, we'll give it a once over with a paint brush, pile it all up on a pallet, and send you back up with it to the chieftain.", completion = "Genius! Now, where's that gold paint? I know it's around here somewhere.", sourceObjectiveStatus = "unverified-source-field" }
quests[25776] = { id = 25776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sethria's Demise", description = "While you've been raiding Sethria's nest, messages have been flying back and forth between here and the shrine. Skylord Omnuron was at first reluctant, but I've persuaded my fellow druids to risk a direct assault on Sethria herself.\n\nEveryone agreed to my plan... provided YOU spearhead the attack.\n\nTake this signal rocket and engage Sethria on the far ridge. When she reveals her true colors and shifts to her dragon form, fire the rocket and backup will arrive to help you!", sourceObjective = "Slay the dragon Sethria. Once she reveals her true form, you will need to use the signal rocket to call in reinforcements!", progress = "If a minor dragon like Sethria can cause us so many problems, I hate to see what else Twilight's Hammer has in store...", completion = "Sethria is slain! I knew it was worth the risk.\n\nI'll stay here to look for survivors, but I imagine they'll want to see you back at the shrine.", sourceObjectiveStatus = "unverified-source-field" }
quests[25777] = { id = 25777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onwards to Menethil", description = "This news needs to get to Menethil as soon as possible. I'll send you along on my fastest ram, {name}.\n\nHe knows the way, just make sure you're steady in the saddle and hold on tight.\n\nDon't dawdle around the camp. We've got to send word quickly!", sourceObjective = "Deliver the Slabchisel Report to Captain Stoutfist in Menethil Harbor.", progress = "Welcome to Menethil, stranger. I hope you've got good news or a stiff drink with you.", completion = "Let's take a look here.\n\nOh, this is just lovely. \"Significant geological instabilities\"? \"Threat of sudden, massive topological destabilization\"?\n\nNice to hear that somethin' bad might happen around here. I guess we'll just pick up our flooded town and fly it off somewhere safe!\n\nBah!", sourceObjectiveStatus = "unverified-source-field" }
quests[25778] = { id = 25778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fake Gold for Black Gold", description = "Now that the \"gold\" is ready, I want you to take it up to Khan Ablinh. He'll be so overwhelmed, I bet he'll offer to help us setup the drilling rigs. We could use the horsepower.\n\nHaha, get it? Horsepower?", sourceObjective = "Deliver the Pallet of \"Gold\" to Khan Ablinh at the Splithoof Heights in Thousand Needles.", progress = "What's this? That is a lot of gold you have there.", completion = "Just put it down on the ground, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25779] = { id = 25779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fake Gold for Black Gold", description = "Now that the \"gold\" is ready, I want you to take it up to Khan Blizh. He'll be so overwhelmed, I bet he'll offer to help us setup the drilling rigs. We could use the horsepower.\n\nHaha, get it? Horsepower?", sourceObjective = "Deliver the Pallet of \"Gold\" to Khan Blizh at the Splithoof Heights in Thousand Needles.", progress = "What's this? That is a lot of gold you have there.", completion = "Just put it down on the ground, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25780] = { id = 25780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Menethil Keep", description = "We'd barely pulled ourselves together after the flood when the Dark Iron hit the town. My men and I all rushed to defend the townsfolk, but the crazed fools retreated right into the keep itself.\n\nThey're holed up good, and we can't destroy the keep. Not with half the town in ruins already.\n\nTake my place, {name}. I'd take the leader on myself if he hadn't dealt me this blow. Enter the keep, slay Horghast, and bring this to an end!", sourceObjective = "Kill Horghast Flarecrazed.", completion = "He's dead! Thank the Makers...\n\nI don't like the looks of them, lad. The Dark Iron I've tussled with were never this crazy. Something's getting to these sods...", sourceObjectiveStatus = "unverified-source-field" }
quests[25790] = { id = 25790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Crazzle", description = "I am NOT stupid!\n\nGo back to your master and tell him that there will be NO deal! That is, if you can survive to make it back to him.", sourceObjective = "Speak with Crazzle Sprysprocket at the Splithoof Heights in Thousand Needles.", completion = "THEY WHAT?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25791] = { id = 25791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Riznek", description = "I am NOT stupid!\n\nGo back to your master and tell him that there will be NO deal! That is, if you can survive to make it back to him.", sourceObjective = "Speak with Riznek at the Splithoof Heights in Thousand Needles.", completion = "THEY WHAT?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25792] = { id = 25792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pushing Forward", description = "Most of the mountaineers and steam tanks in Dun Morogh are battling along the Frostmane Front, which is approaching us from the southeast. We can barely hold the trolls back, let alone advance into their village and take on their leader.\n\nThey've blocked our path of approach with mysterious totems that choke mountaineers who come in range, leaving the victims helpless against their enemies. This stone is inscribed with a rune of fire; it should be able to destroy the totems and free our mountaineers.", sourceObjective = "Use the Rune of Fire to destroy 4 Constriction Totems in the Frostmane Front.", progress = "Was the rune able to destroy the totems? Were we too late?", completion = "Finally, some good news from the Frostmane Front. I'll have the mountaineers press their attack immediately. Now, we must signal our gnomish allies at Steelgrill to start their advance.", sourceObjectiveStatus = "unverified-source-field" }
quests[25793] = { id = 25793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deep Reaches", description = "The purpose of this base was to establish a foothold in Stonetalon for Theramore and to open up a supply line to the night elves. The Horde, unfortunately, has given us one hell of a fight. Hellscream's armies are mighty and unrelenting. I haven't seen this type of ferocity from the Horde since the second war.\n\nNow it would appear that the mine the Explorers' League dug out is being used by the Horde to \"backdoor\" us. We need to seal that thing off!", sourceObjective = "Speak to Steeltoe McGee at the Deep Reaches in Stonetalon Mountains.", completion = "Seal it off? That's gonna take some work, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[25794] = { id = 25794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undersea Sanctuary", description = "I believe I've located the author of your note, friend.\n\nIt would seem that he is in desperate need of attention if he is to survive.\n\nI shall attune one of my scrying orbs, that you might see him for yourself.", sourceObjective = "Use Erunak's Scrying Orb to view the location of Deepmist Grotto.", progress = "Have you familiarized yourself with the cavern's location, {name}?", completion = "We must make haste!\n\nAs you can surely see, his time is not long.", sourceObjectiveStatus = "unverified-source-field" }
quests[25795] = { id = 25795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Shrine", description = "Aviana's Egg should have arrived safely back at the Shrine. You should go check on it! Choluna should know how to handle this.\n\nI'll finish the last of our business here and catch up with you later.", sourceObjective = "Return to Choluna at the Shrine of Aviana in Mount Hyjal.", completion = "{name}! Is it true you led an assault against a twilight dragon?\n\nYou are truly a herald of the ancients!", sourceObjectiveStatus = "unverified-source-field" }
quests[25796] = { id = 25796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eminent Domain", description = "It is our destiny to take this oil. Unfortunate that the centaur retreated to here when the sea rushed in.\n\nUnfortunate for them, that is.\n\nThey've spit in our faces, {name}. We made them a generous offer and they made the mistake of not accepting. Now we... you, will show them the error of their ways.\n\nClear the centaur off of the Splithoof Heights. The oil must flow!", sourceObjective = "Slay 15 Splithoof Heights centaurs.", completion = "That'll teach them. You've softened the Splithoof up enough that we should be able to govern them now with a minimal guard presence from the Speedbarge.\n\nThat is, once we've dealt with their supposed air elemental leader.", sourceObjectiveStatus = "unverified-source-field" }
quests[25797] = { id = 25797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eminent Domain", description = "It is our destiny to take this oil. Unfortunate that the centaur retreated to here when the sea rushed in.\n\nUnfortunate for them, that is.\n\nThey've spit in our faces, {name}. We made them a generous offer and they made the mistake of not accepting. Now we... you, will show them the error of their ways.\n\nClear the centaur off of the Splithoof Heights. The oil must flow!", sourceObjective = "Slay 15 Splithoof Heights centaurs.", completion = "That'll teach them. You've softened the Splithoof up enough that we should be able to govern them now with a minimal guard presence from the Speedbarge.\n\nThat is, once we've dealt with their supposed air elemental leader.", sourceObjectiveStatus = "unverified-source-field" }
quests[25798] = { id = 25798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend the Drill", description = "I'm not leaving here empty-handed! Are you?\n\nI bet you were wondering what's in the giant crate. Well, wait no longer. I want you to take one of our drilling rigs to the oil pools and pump us up some crude.\n\nOf course, you should expect the centaurs to attack. Just defend the drill long enough for us to get a barrel or two out of the ground.", sourceObjective = "Defend the Oil Drilling Rig.", completion = "Oil! Black gold! Tanaris Tea!\n\nWe're rich! We just have to clear out the remaining pesky centaur. I'm sure with all the money we're going to make, we can relocate them to some other bluff.", sourceObjectiveStatus = "unverified-source-field" }
quests[25799] = { id = 25799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend the Drill", description = "I'm not leaving here empty-handed! Are you?\n\nI bet you were wondering what's in the giant crate. Well, wait no longer. I want you to take one of our drilling rigs to the oil pools and pump us up some crude.\n\nOf course, you should expect the centaurs to attack. Just defend the drill long enough for us to get a barrel or two out of the ground.", sourceObjective = "Defend the Oil Drilling Rig.", completion = "Oil! Black gold! Tanaris Tea!\n\nWe're rich! We just have to clear out the remaining pesky centaur. I'm sure with all the money we're going to make, we can relocate them to some other bluff.", sourceObjectiveStatus = "unverified-source-field" }
quests[25800] = { id = 25800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Life Gives You Crabs", description = "There's a lot to do here, {class}, but we need to keep an eye out for the gifts of fate.\n\nWhen the flood rolled in, right over our houses, it swept a good number of ocean dwellers with it. Menethil Bay's full of crabs now, large and ripe for the picking.\n\nWhen life gives you crabs, go crab fishing, I say. Bring me back the largest, meatiest claws you can find and I'll pay you.", sourceObjective = "Collect 5 Meaty Crawler Claws from Harbor Crawlers.", progress = "Don't bother with the smaller claws, they're more work to shell than the meat's worth.", completion = "A hearty seafood dinner will lift everyone's spirits and help us get the town back in shape again. Thanks for the help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25801] = { id = 25801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claws from the Deep", description = "Murlocs are crawling out from the deep waters and building their villages on the coastline.  They are harassing our fishers and merchants and must be stopped.\n\nOne of these murlocs, Gobbler, skulks with other bluegill murlocs and harries merchants along the road, always then retreating to the safety of the nearby murloc hovels.  Our merchants are in jeopardy, and we will pay to secure them.\n\nGobbler prowls the river inlet north of here.  Find him, slay his kin, and bring me his head.", sourceObjective = "Collect Gobbler's Head from Gobbler and slay 12 Bluegill Murlocs of any kind.", progress = "Our merchants will not be safe until we are rid of Gobbler and those murlocs.", completion = "Ah, well done {name}.\n\nAccept this as payment for fulfillment of your contract with the Merchant Marines.", sourceObjectiveStatus = "unverified-source-field" }
quests[25802] = { id = 25802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Goods", description = "Not long ago a merchant vessel, the Blind Princess, was raided by murlocs.  Although the ship escaped intact, much of its cargo was dragged overboard by the creatures, including a very valuable statuette of Terenas Menethil.  We want that statuette recovered.\n\nSearch the coastal murloc hovels for crates, barrels and other evidence of lost cargo.  Find the Menethil statuette and return it to me.", sourceObjective = "Search the crates and barrels at the coastal Murloc camps.", completion = "This crate is covered with clawed scratches, and the marks of water damage.  Prying it open reveals soggy and rotted straw, as if something of value was stored in the crate.  You search through the straw...\n\n...and find an armload of red-colored bottles.", sourceObjectiveStatus = "unverified-source-field" }
quests[25803] = { id = 25803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search Continues", description = "You thoroughly search this cluster of murloc hovels, and find no trace of the Menethil statuette.\n\nPerhaps one of the two nearby hovels to the north and northeast will have more clues.", sourceObjective = "Search for the Menethil Statuette.", completion = "This barrel is largely untouched.  Prying it open...\n\n...you are assaulted by the pungent odor of cheese.  It's a little wet, but still tasty!", sourceObjectiveStatus = "unverified-source-field" }
quests[25804] = { id = 25804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search More Hovels", description = "This grouping of murloc hovels, after a thorough inspection, reveals nothing.\n\n...but you're certain that the next clue you find will be fruitful.\n\nOne of the hovels to the north must have the Menethil statuette!", sourceObjective = "Continue searching the Murloc hovels for the Menethil Statuette.", completion = "This barrel is halfway buried amidst the mud and grass ...", sourceObjectiveStatus = "unverified-source-field" }
quests[25805] = { id = 25805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return the Statuette", description = "After pulling the barrel free from the muck and opening it, a silvery figurine is found packed in fine straw.  It depicts a young, long-haired paladin with hammer upraised.\n\nThis must be the Menethil statuette!  You must now return it to Karl Boran in Menethil Harbor.", sourceObjective = "Bring Karl Boran at Menethil Harbor in Wetlands the Menethil Statuette.", progress = "Do you have the statuette?", completion = "The captain of the Blind Princess will be relieved to hear this precious cargo has been recovered.  You've well earned this payment for services rendered.\n\nIt's good to see dependable folk like you, especially in trying times such as these.", sourceObjectiveStatus = "unverified-source-field" }
quests[25806] = { id = 25806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Put the Assass in... Never Mind", description = "Ah, the Explorers' League - such a profound group of morons. Not only do we have tauren ghosts up our butts, the Explorers' League has also managed to open up a backdoor to the primary Horde base in Stonetalon, Krom'gar Fortress.\n\nNow we've got Krom'gar assassins silently executing everyone in the mine.\n\nI need you to head in there and clean house.\n\nI almost forgot to give you these goggles. Put them on immediately. They'll make all the stealthed assassins in the mine plainly visible.", sourceObjective = "Kill 12 Krom'gar Assassins.", sourceObjectiveStatus = "unverified-source-field" }
quests[25807] = { id = 25807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Reborn", description = "I'm convinced that YOU are the herald of Aviana, {name}. It was you who first saw her and rescued her essence from the claws of a dragon.\n\nYes, I believe Aviana is to be reborn into our world. And you shall have the honor of ushering her over the threshold.\n\nTake this incense and burn it before Aviana's egg in the room just above me.\n\nThe ancient awaits, {name}. Our deliverance is here!", sourceObjective = "Use the Herald's Incense before Aviana's Egg at the Shrine of Aviana.", completion = "I ... live.\n\nThose that tried to corrupt me and kidnap my children will soon feel the rake of my talons, {class}. Believe it.\n\nContinue to push forward across Hyjal. I will collect myself and assemble with the other ancients.", sourceObjectiveStatus = "unverified-source-field" }
quests[25808] = { id = 25808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is This Thing On?", description = "<The Gnomecorder crackles with energy. You can hear Lieutenant Paulson on the other end.>\n\nStupid gnome junk... Is ANYBODY there? {name}, are you there?\n\nMaybe <he's/she's> dead.\n\nListen, if you can still hear me, we just got word that a Horde master assassin is in the mines, directing the other assassins. Find her, kill her, report back to me.\n\nPaulson, out.", sourceObjective = "Kill Master Assassin Kel'istra.", progress = "Oh so you are alive.", completion = "Nicely done, {name}! You worked the mines like a pro. Now how about returning my goggles.", sourceObjectiveStatus = "unverified-source-field" }
quests[25809] = { id = 25809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No Man Behind!", description = "Horde monsters!\n\n<Corporal Wocard spits.>\n\nLook at this place! They've wiped out innocents! Civilians!\n\nListen, {name}, you've got to help us. Go into the Deep Reaches and look for surviving miners. If any are still alive they're probably scared witless! Check in the nooks and crannies of the mine. Maybe in mine carts! There are bound to be some left alive and in hiding.", sourceObjective = "Rescue 8 Frightened Miners.", completion = "Thank the Light! You truly are a righteous instrument of power! The Alliance is lucky to you have, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25810] = { id = 25810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hatchery Must Burn", description = "{name}! Choluna spoke true: the goddess has returned! A miracle in our midst.\n\nWhile you were able to kill the twilight dragon Sethria, we have not yet located all of the eggs that the harpies had delivered to her. Thisalee and I have tracked them to a great hatchery constructed within the Firelands. It is not of this realm, so Aviana cannot accompany you.\n\nFly south and enter the flamegate in the center of the valley. Farden Talonshrike has been sent ahead and will be waiting for you within.", sourceObjective = "Travel through the flamegate in the center of the Flamewake in Mount Hyjal. Speak with Farden Talonshrike once you are inside.", completion = "So it's true - Aviana has returned, with you as her herald.\n\nThere's much to be done here. We are deep in the heart of the Firelands. Sethria smuggled stolen eggs from Mount Hyjal here to hatch her own hideous creations - birds of prey, trained for war.\n\nI hope you're ready to fight back!", sourceObjectiveStatus = "unverified-source-field" }
quests[25811] = { id = 25811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shuttin Her Down", description = "To bring this mine down you're gonna need to blow up her support beams. I can provide you with the explosives you'll need, but you're gonna have to trudge through Krom'gar assassins to get to all of the beams.\n\nThe good news, if any exists, is that we always mark our support beams with a big 'X.' Look for the markers and plant this dynamite near 'em. Once you've planted all the dynamite come on back up here and I'll activate the explosives.\n\nKaboom!", sourceObjective = "Plant the Dynamite Bundle at the First Beam, Second Beam, Third Beam and Fourth Beam.", completion = "Here goes nothin'!", sourceObjectiveStatus = "unverified-source-field" }
quests[25812] = { id = 25812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spelunking", description = "Hurry, {name}!\n\nMake your way to that cavern at once.\n\nWe shall go behind you to ensure that you are not followed.", sourceObjective = "Speak to Private Pollard in Deepmist Grotto.", completion = "A... a {race}? Here?\n\nI must be mad...", sourceObjectiveStatus = "unverified-source-field" }
